update content_bodies set title = '明日を想像する MIYAGI', description = 'ベルギーの写真家ロブ・ワルバーズが宮城県を訪れ、震災後の復興の進捗状況を調査します。このプロジェクトは復興庁によって制作され、2021年3月に完成しました。' where id = 'KMXxIK0yw6Y2EKp9Dt8K2';
