update content_bodies set title = '明日を想像する 福島', description = 'スウェーデンの写真家ナタリー・カンタクジーノが福島県を訪れ、地震後の復興の進捗状況を調査します。このプロジェクトは復興庁によって制作され、2021年3月に完成しました。' where id = 'Dh6QtDnEy6MhmFQHUm9UF';
