update content_bodies set title = '加賀百万石回遊ルート', description = '鼠多門の開通と共に誕生した「加賀百万石回遊ルート」。このルートでは、特に写真に収めたくなる美しい金沢の景観を楽しむことができる「インスタ映えコース」を巡ります。' where id = '6STfKltzd6fACLmt4KiLR';
