update content_bodies set title = '≪KYOKA音・語り≫　泉鏡花「照葉狂言」より', description = '慶長7年（1602年）、12世教如上人が東本願寺を興し、加越能三ヵ国の門徒衆が「東末寺」を建立しました。寛永11年（1634年）には現在地に寺基を定め、「金沢東別院」を舞台に、泉鏡花の美しく幻想的な物語が語られます。能と音楽、舞踊が絡む夢の一夜をお楽しみください。' where id = 'vxHftr7PGDYytvw1NjTHN';
update content_bodies set title = 'KYOKA Sound and Story: From Izumi Kyoka''s ''Teruha Kyogen''', description = 'In 1602, the 12th generation of the Teachings of Jōin established the Higashi Hongan-ji temple, leading to the creation of the ''Higashi Matsuji'' by followers from the Kanto, Koshinetsu, and Noto regions. In 1634, the temple was relocated to its current site, where the Kanazawa Higashi Betsuin serves as the stage for a beautiful and fantastical tale by Izumi Kyoka. Experience a dreamlike night where Noh, music, and dance intertwine.' where id = 'kgmGS5A4-48L5cIDjB1nO';
update content_bodies set title = '走井は今日も笑う！', description = '滋賀県栗東市走井集落のイメージ動画です。この里山は活気に満ちており、たくさんの『笑顔』と出会えることを楽しみにしています。走井の住民たちは、地域の活力を示し、笑顔あふれる日常を大切にしています。' where id = 'kPPhWL5aQp3INaO2GVndW';
update content_bodies set title = 'Hashiri: Smiles in Every Step!', description = 'This is an image video of the Hashiri community in Ritto City, Shiga Prefecture. The Satoyama area is vibrant and full of smiles, creating an atmosphere where encounters with joy are anticipated. The community is dedicated to showcasing the lively spirit of Hashiri and its residents.' where id = 'QuNBQkFgpkvooWTTdLStt';
update content_bodies set title = 'いしかわ旅行割キャンペーンPR動画第２弾', description = '「いしかわ旅行割」キャンペーンのPR動画第2弾です。このキャンペーンは、石川県への旅行をお得に楽しむことができる内容となっています。詳細は公式サイトをご覧ください。' where id = 'xUFFNaB4atjmgzP-yU0li';
update content_bodies set title = 'Ishikawa Travel Discount Campaign PR Video Part 2', description = 'This is the second promotional video for the ''Ishikawa Travel Discount'' campaign, which allows travelers to enjoy trips to Ishikawa Prefecture at a more affordable price.' where id = 'H204G9yj2Xwqe7E-MYt7i';
update content_bodies set title = '【栗東ウエルネスツアー】プロモーションムービー', description = '一般社団法人栗東市観光協会が主催する栗東ウエルネスツアーのプロモーションムービーです。このムービーは、栗東市の観光資源やウェルネスの魅力を伝えることを目的としています。観光協会は、地域の特性を活かしたツアーを通じて、訪れる人々に心身のリフレッシュを提供し、地域の活性化を図っています。' where id = '2zHO5QNSxhg0LRmTcMhS3';
update content_bodies set title = 'Ritto Wellness Tour Promotional Video', description = 'This is a promotional video for the Ritto Wellness Tour, organized by the Ritto City Tourism Association.' where id = 'rv_K04VsmFS2SsCvaBXmc';
update content_bodies set title = 'シガリズム体験【食べよう編vol.1】', description = '自分にぴったりのシガリズム体験を探し、滋賀を心ゆくまで楽しむことができます。シガリズムは、琵琶湖をはじめとした自然と共に、滋賀の時間の流れや暮らしを体感し、心のリズムを整える新たな旅の提案です。従来の観光コンテンツに加え、滋賀ならではの文化や伝統産業に焦点を当て、宝物となる素材を掘り起こす体験が提供されます。紹介されている施設には、近江牛の歴史を学びながら絶品のすき焼き調理体験ができる松喜屋や、湧き水を利用した豆腐作り体験と地元の素材を使ったランチが楽しめるたらいち邸があります。' where id = 'AynXuLbxqX05KbbZGM8Js';
update content_bodies set title = 'Shigarhythm Experience: Food Edition Vol. 1', description = 'Explore the perfect Shigarhythm experience and enjoy Shiga to the fullest. Shigarhythm offers a new travel proposal that aligns with the natural flow of time and life in Shiga, including Lake Biwa. It allows you to experience the rhythm of your heart by immersing yourself in the local culture, traditions, and industries. The Shigarhythm experience includes unique activities that go beyond traditional tourism, focusing on the treasures of Shiga''s culture and lifestyle. Featured facilities include Matsukiya, where you can learn about the history of Omi beef and enjoy a cooking experience, and Taraichitei, which offers a private tofu-making experience using spring water, along with a lunch featuring local ingredients prepared in a traditional farmhouse setting.' where id = 'ecTDll6vE00U1MfEj4dbP';
update content_bodies set title = 'シガリズム体験【食べよう編vol.2】', description = '自分にぴったりのシガリズム体験を探し、滋賀を心ゆくまで楽しむことができます。シガリズムは、琵琶湖をはじめとした自然と共に、滋賀の時間の流れや暮らしを体感することで心のリズムを整える新たな旅の提案です。従来の観光コンテンツに加え、滋賀ならではの文化や伝統産業に焦点を当て、宝物となる素材を掘り起こす体験が提供されます。具体的には、BIWAKO AQUA PONICSでのトマト摘み取りとピザ作り、和た与でのでっち羊羹作りなど、地域の生活に深く関わるアクティビティが用意されています。' where id = 'SpMTKsCGo8L-RtBQkJdYJ';
update content_bodies set title = 'Shigarhythm Experience: Let''s Eat Vol. 2', description = 'Explore the perfect Shigarhythm experience and enjoy Shiga to the fullest. Shigarhythm offers a new travel proposal that aligns with the natural flow of time and life in Shiga, including Lake Biwa. By experiencing the local culture, traditions, and industries, visitors can discover valuable materials that embody the essence of ''Shigarhythm.'' The experience includes unique activities such as tomato picking and pizza making at BIWAKO AQUA PONICS, as well as making traditional ''dechi yokan'' at Watayo. These activities allow participants to engage deeply with the local lifestyle and rhythm.' where id = 'a32nr3B6JExVw9j5te2Qz';
update content_bodies set title = 'シガリズム体験【つくろう編vol.1】', description = '自分にぴったりのシガリズム体験を探し、滋賀を心ゆくまで楽しむことができます。シガリズムは、琵琶湖をはじめとした自然と共に、滋賀の時間の流れや暮らしを体感し、心のリズムを整える新たな旅の提案です。従来の観光コンテンツに加え、滋賀ならではの文化や伝統産業に焦点を当て、宝物となる素材を掘り起こす体験が提供されます。田中貞豊鍛刀場では本物の日本刀の材料である玉鋼を使った小刀作り、山脇源平商店では養蚕から真綿づくりの体験ができます。これらの体験を通じて、地域の遺産やリズムに触れることができます。' where id = 'Z05sqRp9YqPb6HXNAaDok';
update content_bodies set title = 'Shigarhythm Experience: Create Edition Vol. 1', description = 'Explore the perfect Shigarhythm experience and enjoy Shiga to the fullest. Shigarhythm offers a new travel proposal that aligns with the natural flow of time and life in Shiga, including Lake Biwa. By experiencing the local culture, traditions, and industries, visitors can discover valuable materials that embody the essence of Shigarhythm. The program includes unique activities such as creating a small knife using tamahagane (Japanese steel) at the Tanaka Sadatoyo Swordsmith and learning the process of silk production and raw silk pulling at the Yamawaki Genpei Shop. These experiences allow participants to connect with the region''s heritage and rhythm.' where id = '82UqrQVTmJ54LVV7fHewa';
update content_bodies set title = '日本遺産ツーリズム（長浜編）～水と祈りの文化 竹生島を訪ねて～', description = '琵琶湖の中で2番目に大きい竹生島は、古くから航海の神様が祭られてきた神聖な島であり、日本遺産・水遺産にも認定されています。この島は「神が宿る島」として信仰を集めてきました。観光船で竹生島港に到着すると、165段の「いのりの階段」を上り、宝厳寺へ向かいます。宝厳寺本堂の本尊・大弁才天や国宝の宝厳寺唐門、西国三十三所観音霊場の第三十番札所である宝厳寺観音堂など、見どころが豊富です。また、都久夫須麻神社では絶景の拝殿からかわらけ投げを楽しむことができます。刺激的な歴史と信仰の旅を映像でお楽しみください。' where id = 'PEaG3ROWPzfUvfVgsIKOd';
update content_bodies set title = 'Japanese Heritage Tourism (Nagahama Edition) - Visiting the Sacred Island of Chikubushima', description = 'Chikubushima, the second largest island in Lake Biwa, is a sacred place where the god of navigation has been worshipped since ancient times. Recognized as a Japanese Heritage and Water Heritage site, it has long been revered as an island where gods reside. Upon arriving at Chikubushima Port by sightseeing boat, visitors begin their journey by ascending the 165 steps of the ''Inori no Kaidan'' leading to Hōgon-ji Temple. Highlights include the main hall housing Daibenzaiten, one of Japan''s three Benzaiten, the splendid national treasure of Hōgon-ji''s Karamon gate, and the Kannon Hall, the 30th sacred site of the Saigoku 33 Kannon pilgrimage. At the Takuhi Shrine, which has a national treasure main hall, visitors can enjoy the unique experience of throwing ''kawarake'' from the scenic worship hall. Enjoy this exciting journey through history and faith in the accompanying video.' where id = '2BbGzOkoqJPbr64yJnhiA';
update content_bodies set title = '日本遺産ツーリズム（彦根編）～彦根城玄宮園と外堀跡を訪ねて～', description = '彦根城は、関ヶ原の戦い直後に築かれた軍事拠点で、江戸時代には三重のお堀に囲まれた水城でした。今回は、池泉回遊式の大名庭園『玄宮園』と、その水源であり防御機能を持つ『外堀跡』を訪れます。特に、玄宮園の池に映る国宝の天守や、明治時代以降に埋め立てられた外堀跡に残る土塁遺構は必見です。映像を通じて、これらの美しい景観をお楽しみください。' where id = 'zRhAyUDg5hewydodh65Oo';
update content_bodies set title = 'Japanese Heritage Tourism (Hikone Edition) - Visiting Hikone Castle Genkyu-en and the Outer Moat Ruins', description = 'Hikone Castle, built shortly after the Battle of Sekigahara, served as a military base crucial for surrounding Osaka Castle. During the Edo period, it was surrounded by a triple moat and various water bodies, making it a water castle. This video showcases the beautifully designed landscape garden ''Genkyu-en,'' which cleverly utilizes water, and the ''Outer Moat Ruins,'' which served as a water source and defense against enemies while being closely tied to the lives of the people. Notable sights include the national treasure of the castle reflected in the pond of Genkyu-en and the earthen structures remaining from the outer moat, which was entirely reclaimed after the Meiji era.' where id = '1jRov7LrPjXfkN5ZxmVBB';
update content_bodies set title = 'いこうぜ♪滋賀・びわ湖 -1min ver-', description = '2024年9月21日より滋賀県の観光キャンペーンが始まります！観る、食べる、体験するという全ての感動をお届けします。滋賀・びわ湖での感動のシガリズムトリップへようこそ。' where id = 'rGjyg0V8L6uusTLA-drH0';
update content_bodies set title = 'Let''s Go! Shiga and Lake Biwa - 1min ver-', description = 'Starting from September 21, 2024, a tourism campaign for Shiga Prefecture will begin! Experience the thrill of seeing, tasting, and engaging in activities. We deliver all kinds of excitement. Welcome to the Shiga Rhythm Trip at Lake Biwa.' where id = 'UXOfsJAfmDb0mMv-w7CLy';
update content_bodies set title = 'いこうぜ♪滋賀・びわ湖 -3min ver-', description = '2024年9月21日より滋賀県の観光キャンペーンが始まります！観る、食べる、体験するという全ての感動をお届けします。滋賀・びわ湖の感動のシガリズムトリップへようこそ。BIWAKOモニュメントや、うなぎ料亭の山重、水郷めぐりなど、様々な魅力を体験できます。' where id = 'CAJcxmUUpD_sbm9Q474dD';
update content_bodies set title = 'Let''s Go! Shiga and Lake Biwa - 3min ver-', description = 'Starting from September 21, 2024, a tourism campaign for Shiga Prefecture will begin! Experience the excitement of seeing, tasting, and engaging in activities. Welcome to the Shiga Rhythm Trip at Lake Biwa, where all emotions are delivered. Explore the BIWAKO monument, enjoy eel cuisine at Yamashige, and take a tour of the water towns.' where id = 'jNUMZYPI6ocMgjSvI6c5p';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 遊び旅篇（2分版）', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムは、自然と調和しながら心のリズムを整える旅へと誘います。人々は焦らず、自然と共にゆっくりと暮らしてきた滋賀の生活や歴史に触れ、自然空間でのアクティビティや地元の人々との何気ない会話を楽しむことができます。様々な体験の中で、滋賀での旅は心のリズムを整える素晴らしい機会となるでしょう。ようこそ、シガリズム、滋賀・びわ湖へ。' where id = 'MZuTquh1_gj1WexWElsHs';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm - Play Travel Edition (2-minute version)', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga to a national audience. The rhythm of Shiga invites you to embark on a journey that harmonizes your heart''s rhythm. It embodies a lifestyle where people move in sync with nature, living slowly and mindfully. Visitors can experience Shiga''s rich history, engage in activities within its natural spaces, and enjoy casual conversations with the locals. Amidst the various experiences, a trip to Shiga is sure to align your heart''s rhythm. Welcome to Shigarhythm, Shiga and Lake Biwa.' where id = 'zDWKMHAUwasJrntKqpZ6Q';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 遊び旅篇（ロング版）', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムに触れ、自然と調和しながら、ゆっくりとした生活を体験する旅へと誘います。滋賀の暮らしや歴史に出会い、自然の中でのアクティビティを楽しみ、地元の人々との何気ない会話を通じて、心のリズムを整えることができるでしょう。滋賀・びわ湖へようこそ、シガリズムの世界へ。' where id = '48VC_afRaj9IrYKDitu_6';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm - Play Travel Edition (Long Version)', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga to a national audience. It invites travelers to experience the rhythm of Shiga, where people live in harmony with nature, taking life slowly and mindfully. Visitors can engage with Shiga''s lifestyle and history, participate in activities in its natural spaces, and enjoy casual conversations with the locals. These experiences are designed to help travelers find their own rhythm and rejuvenate their spirits. Welcome to Shigarhythm, Shiga and Lake Biwa.' where id = 'o0hpaor2q2WJAZhUmEHyL';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 湖南エリア', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムは、自然と調和しながら、焦らずにゆっくりとした生活を送ることを象徴しています。滋賀の歴史や暮らしに触れ、自然の中でのアクティビティを楽しみ、地元の人々との何気ない会話を通じて、心のリズムを整える旅が体験できます。滋賀での体験は、心を豊かにし、訪れる人々にとって特別な時間となるでしょう。ようこそ、シガリズム 滋賀・びわ湖へ。' where id = '_kRoqMkJ-nqQO7ZEIAx48';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm Kōnan Area', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga, reaching out to a national audience. The rhythm of Shiga invites you to embark on a journey that harmonizes your heart''s rhythm. This rhythm embodies a lifestyle where people move in sync with nature, living slowly and mindfully. Visitors can engage with Shiga''s history and lifestyle, participate in activities in its natural spaces, and enjoy casual conversations with the locals. These experiences promise to align your heart''s rhythm, making your visit to Shiga a fulfilling journey. Welcome to Shigarhythm, Shiga and Lake Biwa.' where id = 'R6W7j6r3JB__nZ8vq7pZ3';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 甲賀エリア', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムは、自然と共にゆっくりとした生活を楽しむことを促し、訪れる人々に心のリズムを整える旅を提供します。地元の暮らしや歴史、自然のアクティビティ、そして滋賀の人々との何気ない会話を通じて、心に残る体験が得られるでしょう。滋賀・びわ湖へようこそ、シガリズムの世界へ。' where id = 'CrftD9fSlVmwoc2DPLPyj';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm Koka Area', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga, reaching out to a national audience. The rhythm of Shiga invites travelers to align their hearts with nature, encouraging a slow and mindful way of living. Visitors can engage with the local lifestyle, history, and natural activities, as well as enjoy casual conversations with the people of Shiga. These experiences promise to harmonize the heart''s rhythm, making for a fulfilling journey. Welcome to Shigarhythm, Shiga, and Lake Biwa.' where id = 'c_U-QheVqrDmuLTBQj3Jj';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 大津エリア', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムは、自然と調和しながら、焦らずにゆっくりとした生活を送ることを大切にしています。滋賀の歴史や文化に触れ、自然の中でのアクティビティを楽しみ、地元の人々との何気ない会話を通じて、心のリズムを整える旅を提供します。滋賀・びわ湖へようこそ、シガリズムの世界へ。' where id = '8bJaHv_hpYp4GilDj2iEa';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm Otsu Area', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga, reaching out to a national audience. The rhythm of Shiga embodies a lifestyle that harmonizes with nature, allowing people to live slowly and mindfully. Visitors can engage with Shiga''s history, enjoy activities in its natural spaces, and have casual conversations with the locals. These experiences are designed to help travelers find their own rhythm and rejuvenate their spirits. Welcome to Shigarhythm, Shiga and Lake Biwa.' where id = 'QKrgWQW_ZZLvUlFvtV4kt';
update content_bodies set title = '【滋賀県公式観光PR動画】シガリズム 湖西エリア', description = 'シガリズムは、滋賀の魅力を全国に発信する新しい観光スタイルを提案します。滋賀のリズムは、人々が自然と調和しながら、焦らずにゆっくりと生活してきたことを反映しています。訪れる人々は、滋賀の暮らしや歴史に触れ、自然の中でのアクティビティを楽しみ、地元の人々との何気ない会話を通じて心のリズムを整える旅を体験できます。ようこそ、シガリズムの滋賀・びわ湖へ。' where id = 'esO3WrAgToRSFkkYsgKBv';
update content_bodies set title = 'Shiga Prefecture Official Tourism PR Video: Shigarhythm Lake West Area', description = 'Shigarhythm promotes a new style of tourism that reflects the essence of Shiga to a national audience. It invites travelers to experience the rhythm of Shiga, where people live in harmony with nature, taking life slowly and mindfully. Visitors can engage with Shiga''s lifestyle and history, participate in activities in its natural spaces, and enjoy casual conversations with the locals. These experiences are designed to help travelers find their own inner rhythm. Welcome to Shigarhythm, Shiga and Lake Biwa.' where id = 'T2ryTo6b5PFzbZ3vwphLe';
update content_bodies set title = '新鮮な風の街。 -赤穂市プロモーションムービー- [ショートバージョン]', description = '赤穂市は、忠臣蔵の物語で世界的に有名で、2021年に70周年を迎えました。この記念すべき年を祝うために、赤穂市の歴史を振り返りながら、現在の赤穂の姿を記録した動画を制作しました。ドローンや最新の4Kカメラで撮影された美しい映像をお楽しみください。しかし、最新技術を用いても、赤穂市の魅力をすべて描写することは不可能です。ぜひ赤穂市を訪れ、その魅力を体験してください。皆様のご来訪をお待ちしております。' where id = '2QfVrFcFJ3TC-V9Mw76HA';
update content_bodies set title = 'The city with fresh wind. -Ako city promotion movie- [Short version]', description = 'Ako City, renowned globally for its Chushingura story, celebrated its 70th anniversary in 2021. To commemorate this milestone, a video was created showcasing the current state of Ako while reflecting on its history. The video features stunning visuals captured with drones and the latest 4K cameras. Despite the advanced technology used, it is impossible to capture all the attractions of Ako City. Visitors are encouraged to come and experience the charm of Ako City in person, as they are always welcomed.' where id = 'NdUzN7tG3IVjMl7Is9N0K';
update content_bodies set title = '新鮮な風が吹く街 -赤穂市プロモーションムービー-', description = '赤穂市は、忠臣蔵の物語で世界的に有名であり、2021年に70周年を迎えました。この記念すべき年を祝うために、赤穂市の現在の姿を記録した動画が制作され、赤穂市の歴史を振り返っています。ドローンや最新の4Kカメラを使用した美しい映像を楽しむことができます。しかし、最新技術を用いても、赤穂市の魅力をすべて描写することは不可能です。ぜひ赤穂市を訪れ、その魅力を体験してください。私たちはいつでもお待ちしています。' where id = 'F-RybXq9M2l3p3WoxgojX';
update content_bodies set title = 'The city with fresh wind. -Ako city promotion movie-', description = 'Ako City, renowned globally for its Chushingura story, celebrated its 70th anniversary in 2021. To commemorate this milestone, a video was created showcasing the current state of Ako while reflecting on its history. The video features stunning visuals captured with drones and the latest 4K cameras. Despite the advanced technology used, it is impossible to capture all the attractions of Ako City in the video. Visitors are encouraged to come to Ako City to experience its unique charm firsthand. The city always welcomes guests.' where id = 'VY0_EQtw9GN7Kx2V_kniV';
update content_bodies set title = '47人の侍の物語が始まったAKO城', description = 'このドキュメンタリーは、城が本当に必要とされていなかった時代に建設されたAKO城を探ります。AKO城は、当時の最先端の軍事科学である甲州流軍学を駆使して建てられました。この城の歴史的な重要性と建築的特徴は、訪れる価値のある魅力的な目的地となっています。' where id = '0AqfQBi_40U6irt5j4xbl';
update content_bodies set title = 'Ako Castle: The Beginning of the 47 Samurai''s Story', description = 'This documentary explores Ako Castle, a unique fortress built during a time when castles were not essential, showcasing the advanced military science of the Koshu School. The castle''s historical significance and architectural features make it an intriguing destination for visitors.' where id = 'q6kTfQU1-jxl5s8mkcHlH';
update content_bodies set title = 'Sel de la vie | 旅は人生の塩', description = '2人のシェフが兵庫県の赤穂地域を巡り、その地域で有名な新鮮な農産物を味わうためにキッチンバスに乗り込みます。赤穂は2019年に日本遺産に認定され、塩に関連する41の歴史的・文化的遺産があります。' where id = 'SxWdp7pYhHWuYO5aVa9jV';
update content_bodies set title = 'Sel de la vie | Traveling is the salt of life', description = 'Two chefs embark on a culinary journey through the Ako region of Hyogo, eager to explore the area''s renowned fresh produce. The region is celebrated for its salt, and in 2019, Ako was recognized as a certified Japan Heritage site, featuring 41 historical and cultural heritages related to salt.' where id = 'zP-YznwAnn_qSa7O8p9G7';
update content_bodies set title = '高山日本 | シネマティック旅行映画', description = 'この旅行映画は、日本の美しい地域、高山の素晴らしい風景を紹介しています。乗鞍岳などの息をのむような景色が広がり、高山の壮大な自然と高山祭りの興奮を感じることができます。メインカメラにはSony a7S IIIを使用し、レンズにはSony SEL20F18GとSony SEL50F18Fを使用しています。サブカメラにはGoPro HERO 10 BLACK、ドローンにはDJI Mini 2を使用して追加の映像を撮影しています。音楽にはREYNARD SEIDELの「Rising Hope」とCHRISTOFFER MOE DITLEVSENの「The Fellowship」が使用されています。InstagramやTwitterでクリエイターをフォローして、最新情報をチェックしてください。' where id = 'aWDgg85vxa22r6txqFEMN';
update content_bodies set title = 'TAKAYAMA JAPAN | Cinematic Travel Film', description = 'This travel film showcases the stunning beauty of Takayama, Japan, featuring breathtaking landscapes such as Norikura-dake. The film captures the essence of Takayama''s spectacular nature and the vibrant atmosphere of the Takayama Festival. The main camera used is the Sony a7S III, complemented by lenses including the Sony SEL20F18G and Sony SEL50F18F. Additional footage is captured with a GoPro HERO 10 BLACK and aerial shots from a DJI Mini 2 drone. The film is accompanied by music tracks ''Rising Hope'' by Reynard Seidel and ''The Fellowship'' by Christoffer Moe Ditlevsen. Follow the creator on Instagram and Twitter for more updates.' where id = 'uGpzLkvjWxi6x3XMlGOef';
update content_bodies set title = '沖縄日本 | シネマティックトラベルフィルム', description = '沖縄は日本の美しい島の一つで、手つかずの自然の驚異が数多く存在します。制作者は、自身の目で見た素晴らしい景色を共有し、この島をもっと多くの人に知ってもらいたいと考えています。沖縄のハイライトを紹介するこのフィルムは、Sony a7S IIIカメラやさまざまなレンズ、GoPro HERO 10 Black、DJI Mini 2ドローンを使用して撮影されています。音楽はLUWAKSの「Parallax」です。制作者はInstagramとTwitterでフォロワーを募っています。' where id = 'cliPeBjMB5zC6_yIfG7XV';
update content_bodies set title = 'OKINAWA JAPAN | Cinematic Travel Film', description = 'Okinawa is a stunning island in Japan, known for its pristine natural beauty. The creator shares personal experiences of the breathtaking sights encountered on the island, aiming to introduce more people to its wonders. The film showcases highlights of Okinawa, captured using a Sony a7S III camera, along with various lenses, a GoPro HERO 10 Black, and a DJI Mini 2 drone. The background music is ''Parallax'' by LUWAKS. Viewers can follow the creator on Instagram and Twitter for more updates.' where id = 'tkAVENVW2TNFNTic3l9u9';
update content_bodies set title = '岡山日本 - 倉敷、総社、高梁 - | シネマティックトラベルフィルム', description = 'このトラベルフィルムでは、秋の岡山の美しさを紹介しています。美しい秋の紅葉、素晴らしい山の城、工場の夜景、そして西洋と日本の文化が融合した神秘的な街並みが描かれています。この地域は訪れる価値がある場所です。撮影にはSony a7S IIIカメラを使用し、Sony SEL20F18GやSIGMA 24-70mm F2.8 DG DN | Artなどのレンズ、空撮にはDJI Mini 2ドローンを使用しています。音楽にはJo WandriniとTrevor Kowalskiの楽曲が使われています。' where id = 'x4yoMa1q2X_b92i_R-iJm';
update content_bodies set title = 'OKAYAMA JAPAN -Kurashiki, Soja and Takahashi- | Cinematic Travel Film', description = 'This travel film showcases the beauty of Okayama, Japan during autumn. It features stunning autumn foliage, impressive mountain castles, and captivating night views of factories. The film also highlights the unique cityscape where Western and Japanese cultures intertwine, making it a region worth visiting. The filmmaker uses a Sony a7S III camera with various lenses, including the Sony SEL20F18G and SIGMA 24-70mm F2.8 DG DN | Art, along with a DJI Mini 2 drone for aerial shots. The background music includes tracks by Jo Wandrini and Trevor Kowalski.' where id = 'sdmf3PU80H8QGKkZZKE5N';
update content_bodies set title = 'SUO OSHIMA JAPAN | シネマティックトラベルフィルム', description = 'この夏、私は日本の美しい島、周防大島を探検しました。この島はハワイの姉妹都市であり、夏の間は毎週フラダンスフェスティバルが開催されます。美しい海の景色を楽しみ、風光明媚な山々でハイキングもしました。この体験は、周防大島の自然の美しさと文化の豊かさを示す真のトロピカルアドベンチャーでした。旅の記録には、主にSony a7S IIIを使用し、レンズにはSony SEL20F18GとSony SEL50F18Fを使用しました。また、追加の映像にはGoPro HERO 10 BLACKを使用しました。音楽はOOYYの「Changli」です。' where id = 'n6Jdwe-DJDzHbE57Vq24S';
update content_bodies set title = 'SUO OSHIMA JAPAN | Cinematic Travel Film', description = 'This summer, I had the opportunity to explore Suo Oshima, a beautiful island in Japan that is a sister city to Hawaii. The island hosts weekly hula dance festivals throughout the summer, adding to its vibrant culture. I also enjoyed the stunning ocean views and went hiking in the picturesque mountains. This experience was a true tropical adventure, showcasing the natural beauty and cultural richness of Suo Oshima. My main camera for capturing this journey was the Sony a7S III, complemented by the Sony SEL20F18G and Sony SEL50F18F lenses, along with a GoPro HERO 10 BLACK for additional footage. The music accompanying the film is ''Changli'' by OOYY.' where id = 'VBd2Rq1sYXmKeUMtjaXWX';
update content_bodies set title = 'SUWA JAPAN | シネマティックトラベルフィルム', description = 'この夏、私は日本の諏訪地域を探検しました。そこには日本アルプスや壮大な山々、神秘的な森林、そして諏訪湖周辺の歴史的な場所があります。諏訪の人々の心は自然への信仰と諏訪大社に根ざしています。山々や歴史的な場所をハイキングする中で、彼らの文化にも感銘を受けました。この冒険を皆さんと楽しめることを願っています。' where id = '2vw_-QN8buVFNEIk_jJUp';
update content_bodies set title = 'SUWA JAPAN | Cinematic Travel Film', description = 'This summer, I explored the Suwa area in Japan, known for its stunning landscapes including the Japanese Alps, dense forests, and historical sites around Lake Suwa. The local people''s deep connection to nature and their faith, particularly in the Suwa-taisha shrine, left a lasting impression on me. Hiking through the mountains and visiting historical landmarks allowed me to appreciate their rich culture. I hope you enjoy this adventure with me.' where id = 'ajaPsqnH32cafDCRQq396';
update content_bodies set title = '長浜日本 | シネマティック旅行映画', description = 'このシネマティック旅行映画では、日本の長浜地域を探索し、美しい山々や日本最大の湖にある神秘的な孤島、中世から続く感情豊かな城下町を紹介しています。映像に収められた体験は本当に特別であり、撮影に協力してくれた「サムライ」に感謝の意を表しています。撮影にはSony a7S IIIカメラを使用し、Sony SEL20F18GやSony SEL50F18Fなどのレンズ、さらにGoPro HERO 10 BLACKも使用されています。背景音楽はOOYYの「Lepiten Falls」です。' where id = 'Xckw40xZ-iObcnURhPiHu';
update content_bodies set title = 'NAGAHAMA JAPAN | Cinematic Travel Film', description = 'In this cinematic travel film, the creator explores the Nagahama area of Japan, showcasing its stunning mountains, a mysterious isolated island on Lake Biwa, and an emotional castle town with a rich history dating back to the Middle Ages. The experiences captured in the video are described as truly special, and the creator expresses gratitude to the ''Samurais'' who participated in the filming. The film is shot using a Sony a7S III camera and features lenses such as the Sony SEL20F18G and Sony SEL50F18F, along with a GoPro HERO 10 BLACK for additional footage. The background music is ''Lepiten Falls'' by OOYY.' where id = 'BzNpx57e1cmK8M1nfBjaI';
update content_bodies set title = '『City in Blue』', description = '『OUR STORIES : from OTARU』は、4K高解像度で制作された観光プロモーションビデオシリーズです。オタル市を訪れる観光客を惹きつけることを目的としており、2本の5分間のビデオ（「オタル版」と「北後志版」）と、インタビューを含む6本の1分間のビデオで構成されています。このプロジェクトは、オタルの美しさと魅力を紹介し、季節の移り変わりを体験する住民たちの穏やかな生活と海とのつながりを強調しています。制作は福島圭介、監督は伊藤宏樹、音楽は大村しのが担当しています。合計の動画の長さは17分42秒で、英語と日本語の字幕が付いています。' where id = 'nJGwYp8MCfU8pAJWDoVg3';
update content_bodies set title = 'City in Blue', description = '"OUR STORIES: from OTARU" is a promotional video series produced in 4K high definition to attract tourists to Otaru City. The series includes two 5-minute videos, "Otaru Version" and "KitaShiribeshi Version," along with six 1-minute videos featuring interviews. The project showcases the beauty and allure of Otaru, highlighting its connection to the ocean and the tranquil lives of its residents as they experience the changing seasons. The video series is produced by FUKUSHIMA KEISUKE and directed by ITO HIROKI, with music by OMURA SHINO. The total duration of the videos is 17 minutes and 42 seconds, available with English and Japanese subtitles.' where id = 'Uns5oVJJAIJnx-k_0D08p';
update content_bodies set title = 'Vol.2 - PRODUCT 「歴史的・文化的ギフト」', description = '北海道の開拓時代に、多くの人々が小樽を訪れ、さまざまな商品や文化を持ち込みました。この影響で「製造業」が栄え、明治時代から続く老舗企業も存在します。現在、小樽ではその歴史を生かした新しい商品が次々と生まれています。『OUR STORIES : from OTARU』というプロモーションビデオシリーズは、観光客を惹きつけることを目的としており、2本の5分間の動画と6本の1分間のインタビューを含んでいます。このプロジェクトは、小樽の文化遺産と製品開発における創造性を強調しています。' where id = '4q4d3jGxymKoVtY9_7-P8';
update content_bodies set title = 'Vol.2 - PRODUCT ''Historical and Cultural Gifts''', description = 'During the pioneering period of Hokkaido, Otaru attracted many visitors who brought various goods and cultural influences. This led to a flourishing of manufacturing, with some companies still operating since the Meiji era. Today, Otaru continues to innovate, creating new products that reflect its rich history. The promotional video series ''OUR STORIES: from OTARU'' aims to attract tourists by showcasing the city''s unique offerings, including two 5-minute videos and six 1-minute interviews. The project highlights Otaru''s cultural heritage and ongoing creativity in product development.' where id = '4ve_B3JlrNAsGJpX3-Lyn';
update content_bodies set title = 'Vol.1 - CITYSCAPE 「Next Hundred Years」 "OUR STORIES : from OTARU"', description = '小樽市は、自治体設立100周年を迎え、物流港への移行を通じて過去100年間に得たものと失ったものを振り返っています。この変化は、今後の100年にわたる小樽の未来に影響を与えるでしょう。小樽には多くの歴史的・文化的遺産があり、発展の基盤となった港から新たな活気が生まれています。このプロジェクトは、観光客を惹きつけるためのプロモーションビデオシリーズを含み、2本の5分動画と6本の1分インタビューが制作され、すべて4K高解像度で提供されています。' where id = 'bXPsL0CIN5_kEuUbfRtdy';
update content_bodies set title = 'Vol.1 - CITYSCAPE 「Next Hundred Years」 "OUR STORIES : from OTARU"', description = 'Otaru is commemorating the centennial of its municipal organization, reflecting on the gains and losses experienced over the past century as it transitioned into a logistics port. This transformation will inform the city''s future for the next hundred years. Otaru is rich in historical and cultural heritage, and a new vibrancy is emerging from the port that was pivotal to its development. The project includes a promotional video series aimed at attracting tourists, featuring two 5-minute videos and six 1-minute interviews, all produced in 4K high definition.' where id = 'DlyMxnn4F_tN6eY8DtTD_';
update content_bodies set title = '【公式】キャナルシティ博多 観光PR動画＃キャナルシティ博多　＃福岡観光', description = 'キャナルシティ博多の周辺には、多くの魅力的な観光地があります。福岡では「観る」ことと「食べる」ことを存分に楽しむことができます。キャナルシティ博多を起点に、福岡を巡る旅に出かけてみませんか。この動画では、太宰府天満宮、福岡タワー、マリンワールド海の中道、大濠公園、糸島、そしてキャナルシティ博多自体など、さまざまな観光スポットが紹介されています。' where id = 'vxmuwNXRQHuDTpgiIb4vG';
update content_bodies set title = 'Canal City Hakata Official Tourism PR Video #CanalCityHakata #FukuokaTourism', description = 'Canal City Hakata is surrounded by numerous attractive tourist destinations. Fukuoka offers a delightful experience of ''sightseeing'' and ''dining''. Why not embark on a journey to explore Fukuoka starting from Canal City Hakata? The video introduces various tourist spots including Dazaifu Tenmangu Shrine, Fukuoka Tower, Marine World Uminonakamichi, Ohori Park, Itoshima, and Canal City Hakata itself.' where id = '16hLV5-Rn5mkrcEQwW3sZ';
update content_bodies set title = '横林産原木椎茸『霧源』', description = '里山の生産者から、届けたい想いがあります。' where id = 'pEILgiVc9hUDF48P-rvlT';
update content_bodies set title = 'Yokobayashi''s Raw Shiitake Mushrooms ''Kiri-gen''', description = 'There is a heartfelt message from the producers in the satoyama (village forest) that they want to convey.' where id = 'yEN8nA7cJh6PHf_hFcRdE';
update content_bodies set title = '横林の暮らし～記憶と風景を紡ぐ～', description = '横林自治振興協議会は、地域の暮らしを映像で表現しました。人がいなくなると、地域の記憶や風景も変わっていきます。みんなにとって大切なものを、これからも守っていくことが重要です。' where id = 'pIo3iFV-riV03SR0st9jF';
update content_bodies set title = 'Life in Yokobayashi - Weaving Memories and Landscapes', description = 'The Yokobayashi Community Promotion Council has created a video reflecting the life in the region. As people leave, the memories and landscapes of the area change. It is essential to preserve what is dear to everyone for the future.' where id = 'ZRwV0DSEiwkmszs748RYp';
update content_bodies set title = '釧路のソウルフード「鉄板スパゲティ」', description = '熱い鉄板の上でジュージューと音を立てる「鉄板スパゲティ」は釧路のソウルフードです。ミートソースだけでなく、塩味のスパゲティも楽しめます。熱された鉄板に盛られているため、最後の一口まで熱々で美味しくいただけます。この料理は地元の人々に長年愛されており、釧路を訪れた際にはぜひ味わっていただきたい一品です。' where id = 'R7r3WytsDWJ_eNnsPs2xK';
update content_bodies set title = 'Teppan Spaghetti', description = 'Teppan Spaghetti, sizzling on a hot iron plate, is a beloved soul food of Kushiro. This dish features not only a meat sauce version but also a salt-flavored spaghetti. Served on a heated iron plate, it remains hot and delicious until the very last bite. Locals have cherished this dish for a long time, making it a must-try when visiting Kushiro.' where id = 'K40o2Nd-rkGySGPz0Py5z';
update content_bodies set title = 'Inspire Your Soul ～Find Your YOKOHAMA～', description = '横浜は新しい発見とワクワクする高揚感に満ちた魅力的な街です。感性を磨くような体験から、穏やかでリラックスできる瞬間まで、日常生活からの逃避を助ける様々な体験が用意されています。気軽に訪れるだけで非日常へとスイッチが切り替わり、心躍るエキサイティングな体験や穏やかな時間が待っています。' where id = '-7Ndt9I24zhzJKJRw5KSy';
update content_bodies set title = 'Inspire Your Soul ～Find Your YOKOHAMA～', description = 'Yokohama is a captivating city that offers a wealth of new discoveries and excitement to engage your senses. It provides a range of experiences, from thrilling adventures to serene moments of relaxation, allowing you to escape the routine of everyday life. The city invites you to switch to an extraordinary experience simply by visiting, where exhilarating activities and peaceful times await.' where id = 'x_WLVUvkTHCGQ6pvJRBZ9';
update content_bodies set title = 'サイクルアドベンチャー阿寒', description = '阿寒は、阿寒摩周国立公園の豊かな自然を満喫できる町です。火山、森、湖が織りなす美しい風景と、阿寒湖温泉に今も息づくアイヌ文化が魅力です。サイクリングやカヌーなど、さまざまなアクティビティを通じて大自然を楽しむことができます。北海道を代表する温泉地である阿寒湖温泉を満喫する方法を紹介します。' where id = 'CAAZjlGnmTtAVLLD8M9fc';
update content_bodies set title = 'Cycle Adventure Akan', description = 'Akan is a town where you can fully enjoy the rich nature of Akan Mashu National Park. The area features a blend of volcanoes, forests, and lakes, along with the Ainu culture that still thrives in the Akan Lake hot springs. Visitors can engage in various outdoor activities such as cycling and canoeing to experience the great outdoors to the fullest. This guide introduces ways to enjoy the renowned hot spring area of Akan Lake.' where id = 'UP6Av63rillNbCVUjz0al';
update content_bodies set title = 'KUSHIRO Hokkaido Japan　釧路グルメ編', description = '自然豊かなまち「釧路」は、釧路湿原と阿寒摩周の2つの国立公園を有しています。釧路の魅力的なグルメには、港町ならではの新鮮な魚介を炭火で焼く「炉ばた焼き」、釧路和商市場の「勝手丼」、名物の「つぶ焼き」、そして「スパカツ」や「釧路そば」といったソウルフードがあります。美しい自然と美味しい料理、素敵な宿泊施設が揃う釧路をぜひ満喫してみてください。詳しくは、釧路・阿寒湖観光公式サイトをご覧ください。' where id = 'M3ZF6F1adj6dAxPMyu-hO';
update content_bodies set title = 'KUSHIRO Hokkaido Japan - Gourmet Edition', description = 'Kushiro, a city rich in nature with two national parks, Kushiro Wetland and Akan Mashu, offers a variety of delicious local cuisine. Highlights include ''Robatayaki,'' where fresh seafood is grilled over charcoal, ''Katte Don'' from Kushiro Washo Market, ''Tsubuyaki,'' and local soul food like ''Spakatsu'' and ''Kushiro Soba.'' The city is not only known for its natural beauty but also for its delightful food and accommodations. Experience the charm of Kushiro and explore more on the official Kushiro and Lake Akan tourism website.' where id = 'Aq8SCsfwDN46rvBJRN85x';
update content_bodies set title = '分散型旅行を応援します！北海道 釧路編', description = '新しい旅は、新しい私から。「分散型」で旅に出よう！このアプローチでは、旅行の時間と場所を分散させることを推奨しています。週末や連休の人気観光地を訪れるのではなく、平日の朝や夕方、夜に出かけて、独特の景色や魅力を楽しむことを提案します。また、知られざる魅力的な場所を訪れることで、よりリラックスした楽しい旅行体験が得られます。' where id = 'VKx4czDxqSCWekuzIAFko';
update content_bodies set title = 'Supporting Decentralized Travel! Kushiro, Hokkaido Edition', description = 'Experience a new journey with a new you through decentralized travel! This approach encourages travelers to spread out their travel times and locations. Instead of visiting popular tourist spots during weekends or holidays, consider exploring during weekdays, particularly in the morning, evening, or night, to enjoy unique scenery and attractions. Additionally, venture beyond the well-known destinations to discover charming places across various regions, allowing for a more relaxed and enjoyable travel experience.' where id = '2IoGWIs8FfW5NAwjOiuTW';
update content_bodies set title = '釧路の四季', description = '釧路は北海道に位置し、四季折々の美しさを体験できる観光地です。訪れる人々は、季節ごとに変わるさまざまなアトラクションやアクティビティを楽しむことができ、自然や文化を通じてユニークな体験ができます。詳細については、提供されたリンクを参照してください。' where id = 'XRr8trsHMavTsDM8FrB8F';
update content_bodies set title = 'KUSHIRO Four Seasons', description = 'Kushiro, located in Hokkaido, Japan, is a destination that showcases the beauty of all four seasons. Visitors can explore various attractions and activities that change with the seasons, making it a unique place to experience nature and culture throughout the year. For more information, you can visit the provided link.' where id = 'cZ-av7pbqt-a32a86IQoY';
update content_bodies set title = '楽しさいっぱい草津！　『草津温泉夜景散策』　～草津温泉イベント紹介～', description = '草津温泉では楽しいイベントがたくさん用意されています。温泉と一緒にイベントを楽しむことで、よりわくわくする旅行が実現します。夜景散策では、草津温泉の夜の楽しみ方をガイドし、普段体験できない特別な体験や主要な観光スポットに関する豆知識を得ることができます。草津温泉の詳細情報は、https://www.kusatsu-onsen.ne.jp/をご覧ください。' where id = 'VJz-Wo9v-fK2vvIw6dl6b';
update content_bodies set title = 'Enjoy Kusatsu! ''Kusatsu Onsen Night View Walk'' - Introduction to Kusatsu Onsen Events', description = 'Kusatsu Onsen offers a variety of fun events. Enjoy events alongside the hot springs for a more exciting trip! The night view walk guides you through unique nighttime experiences in Kusatsu Onsen, providing insights into special activities that are not usually available, as well as interesting facts about major tourist spots. For more information about Kusatsu Onsen, visit https://www.kusatsu-onsen.ne.jp/' where id = 'LUASHyk21HyCMyFPqeD_-';
update content_bodies set title = '2022 KUSHIRO Hokkaido Japan in 8K - 釧路 [夏]', description = 'この動画は、釧路の美しさを8K解像度で紹介しています。釧路湿原ノロッコ号やアイヌ文化体験、鹿肉の鉄板焼きや釧路ラーメンなどの地元料理を含む様々な観光名所が強調されています。細岡展望台や阿寒湖アイヌコタン、釧路湿原展望台などの重要な場所が登場します。また、阿寒湖周辺のサイクリングや湿原でのカヌー体験も紹介されています。アイヌの伝統舞踊や料理を通じて、アイヌ文化の豊かな遺産を探求することができます。音楽はTaizo Audioによるもので、様々なアーティストやコーディネーターの才能が披露されています。' where id = 'BBjTrK2XadfuSsnc4DtBN';
update content_bodies set title = '2022 KUSHIRO Hokkaido Japan in 8K - Kushiro [summer]', description = 'This video showcases the beauty of Kushiro, Hokkaido, in stunning 8K resolution. It highlights various attractions, including the Kushiro Shitsugen Norroko Train, Ainu cultural experiences, and local cuisine such as teppan grilled venison and Kushiro ramen. Key locations featured are the Hosooka Observatory, Akanko Ainu Kotan, and the Kushiro Marshland Observatory. The video also includes activities like cycling around Lake Akan and canoeing in the marshlands. Viewers can explore the rich cultural heritage of the Ainu people through traditional dances and cuisine. The production features music by Taizo Audio and showcases the talents of various artists and coordinators.' where id = 'm3dNforESxirwjc0ncLlv';
update content_bodies set title = 'KUSHIRO Hokkaido Japan のライブ配信', description = 'この動画は、北海道釧路市のライブ配信について紹介しています。' where id = 'OYTdLzvqzhK8skM9dljYY';
update content_bodies set title = 'Live Streaming from KUSHIRO Hokkaido Japan', description = 'This video introduces the live streaming from KUSHIRO, Hokkaido, Japan.' where id = 'l5df39Gb-26PbsCSNOeW6';
update content_bodies set title = '草津温泉の感染症対策～安心で快適な旅行をひとつになって～', description = '草津温泉では、感染症対策の基礎として「スタッフのマスク着用等の咳エチケット」や「施設内への消毒液の設置」、「飛沫感染防止への工夫」など、８つの指標を制定しました。この指標に基づき、さらなる感染症対策に努め、皆様をお迎えする準備を進めています。また、感染症の拡大防止には、皆様のご協力が不可欠です。この動画には、８つの指標と皆様へのお願いが掲載されていますので、旅行前にぜひご覧ください。～安心で快適な旅行をひとつになって～' where id = '3oFtvIzXpXeOTcEeO2kgO';
update content_bodies set title = 'Infection Control Measures at Kusatsu Onsen - Together for a Safe and Comfortable Trip', description = 'Kusatsu Onsen has established eight key indicators as the foundation for infection control measures, including ''staff wearing masks and practicing cough etiquette,'' ''installation of disinfectants within facilities,'' and ''measures to prevent droplet transmission.'' Based on these indicators, we are making further efforts to enhance infection control and prepare to welcome everyone. Additionally, your cooperation is essential for preventing the spread of infections. This video includes the eight indicators and a few requests for everyone. Please take a moment to watch it before your trip! - Together for a safe and comfortable journey.' where id = '6QaND2aR_vAgivjB6YVE0';
update content_bodies set title = '「Re ・・・」 草津温泉', description = '「ある家族の物語」です。結婚前に草津温泉を訪れたカップルが、時を経て夫婦となり家族として日常を過ごしています。ある出来事をきっかけに再び草津温泉を訪れることになります。そこには多くの笑顔があり、2人で訪れた頃とは異なる幸せな時間が流れています。大切な人や家族と新たな思い出を刻むことができる場所であり、時を超え世代を超えても、その瞬間は特別なものです。撮影場所には湯畑、熱乃湯（「湯もみと踊り」ショー）、西の河原公園、草津温泉スキー場、白根神社、喜びの宿高松、和える宿高松、きむらや別邸が含まれています。キャストには中野絢介、藤澤志帆、嶋原ゆずのが出演しています。制作はＣＯＯＴＳ、監督・脚本は上原三由樹、撮影・編集は花岡正人、制作著作は草津温泉観光協会です。' where id = 'XAX_qqMPzuLGFW-BitQ0Y';
update content_bodies set title = 'Re ・・・ Kusatsu Onsen', description = 'This is a story about a family. A couple visited Kusatsu Onsen before getting married. Over time, they became a family and continued their daily lives. Due to a certain event, they return to Kusatsu Onsen. The place is filled with smiles, and the happiness they experience now is different from when they first visited as a couple. It is a place where they can create new memories with their loved ones and family. Time and generations may pass, but each moment is unique and special. The filming locations include Yubatake, Netsunoyu (with a ''Yumomi and Dance'' show), Nishi no Kawahara Park, Kusatsu Onsen Ski Resort, Shirane Shrine, Joyful Inn Takamatsu, Waeru Inn Takamatsu, and Kimuraya Bettei. The cast features Ayusuke Nakano, Shiho Fujisawa, and Yuzuno Shimabara. The production is by COOTS, directed and scripted by Miyuki Uehara, with filming and editing by Masato Hanaoka, and produced by the Kusatsu Onsen Tourism Association.' where id = 'UxrBSzAR6OC7R1mt7cDbn';
update content_bodies set title = '『草津温泉の温泉力』　コロナ不活化編', description = '草津温泉の最大の魅力は、何と言ってもその温泉自体です。古くから多くの人々の心と身体を癒してきた草津温泉は、酸性泉であり、含まれる温泉成分の絶妙なバランスが強力な殺菌力を持つことが研究されています。この高い温泉力が新型コロナウイルスにどのような効果をもたらすのか、研究結果を動画にまとめました。温泉力の背景を少し覗いてみましょう。研究は草津町と群馬大学の板橋英之教授が行い、動画は草津温泉観光協会とCOOTSが制作しました。なお、撮影のためにマスクを外しているシーンがあります。この研究は、コロナウイルスに感染しない、または治癒することを証明するものではありません。' where id = '4-0xckwH43XWf6AEKSOU2';
update content_bodies set title = 'The Power of Kusatsu Onsen: COVID-19 Inactivation Edition', description = 'Kusatsu Onsen is renowned for its hot springs, which have been soothing the hearts and bodies of many for generations. The hot spring''s acidic quality and the unique balance of its mineral components have been studied for their strong antibacterial properties. This raises the question of how the potent hot springs of Kusatsu may affect the new coronavirus. The findings of this research have been compiled into a video. Let''s take a closer look at the ''power of the hot springs'' and the background that enhances its benefits. The research was conducted by Kusatsu Town in collaboration with Professor Hidetaka Itabashi from Gunma University, and the video was produced by the Kusatsu Onsen Tourism Association and COOTS. Note: Some scenes in the video show individuals without masks for filming purposes. This research does not prove immunity to or recovery from the coronavirus.' where id = 'imH8lZr6-s7vRkt1fOB6b';
update content_bodies set title = '草津温泉の「歴史と進化」　今までとこれから～進化を続ける温泉街～', description = '草津温泉は開湯以来、訪れる人々の心と体を癒し続けてきました。歴史を基盤に、近年では湯畑や西の河原公園を中心に、官民一体でまちづくりが進められています。裏草津地蔵エリアの再開発も完了し、今後は温泉門の建設計画もあります。草津温泉の魅力は、温泉そのものや温泉と共生する文化、自然、そして楽しいまち歩きにあります。「定番の温泉旅行+α」を楽しめることが特徴です。草津温泉は、訪れるたびに新しい顔を見せるよう、常に進化を続けています。草津温泉の未来にご期待ください。' where id = 'DaTWKywEh_xJX65c_E4ek';
update content_bodies set title = 'The History and Evolution of Kusatsu Onsen: A Hot Spring Town in Continuous Development', description = 'Kusatsu Onsen has been healing the hearts and bodies of visitors since its opening. Based on its rich history, recent developments have focused on community building around key areas such as Yubatake and Nishi no Kawara Park, with collaboration between public and private sectors. The redevelopment of the Ura Kusatsu Jizo area has been completed, and plans for the construction of a new hot spring gate are underway. The charm of Kusatsu Onsen lies in its hot springs, the culture that coexists with them, the surrounding nature, and the enjoyable experience of walking through the hot spring town, offering more than just a typical hot spring trip. Kusatsu Onsen is committed to continuously evolving, ensuring that each visit reveals something new. Look forward to the future of Kusatsu Onsen.' where id = '4A0DEx7fNGgyddcJ-_8sW';
update content_bodies set title = 'アレがアレすぎて・・・　#草津温泉', description = '草津温泉をご愛顧いただき、誠にありがとうございます。世界中の皆様にお詫びしたいことがあり、それを動画にしました。日常の中で当たり前と思っていることが、実はそうではないこともあります。どうか寛容な心で最後までご覧いただき、笑ってご容赦いただければ幸いです。皆様により楽しんでいただける温泉地を目指して邁進して参りますので、今後とも草津温泉をご愛顧いただけますようお願い申し上げます。撮影・編集はCOOTS、モデルはDijana Boskovic、葉山こはる、ARA、RYOで、撮影スポットは大滝乃湯、地蔵の湯、泉水館、湯宿みゆき本館です。' where id = '9zYRvvhPA_8Df-a63EdBL';
update content_bodies set title = 'Something Unexpected at Kusatsu Onsen', description = 'We sincerely thank you for your continued support of Kusatsu Onsen. We would like to apologize to everyone around the world for a few things. This has been made into a video. In our daily lives, what seems obvious is not always so. We hope you can watch until the end with a forgiving heart and perhaps even smile. We are committed to making Kusatsu Onsen a more enjoyable destination for everyone. We sincerely hope you will continue to support Kusatsu Onsen in the future. Filming and editing by COOTS, featuring models Dijana Boskovic, Koharu Hayama, ARA, and RYO, with filming locations including Otaki no Yu, Jizo no Yu, Sensuikan, and Yuyado Miyuki Main Building.' where id = '1q1GIQMC0uj_eRfvdUL8X';
update content_bodies set title = '草津温泉の春', description = 'この動画は草津温泉の春について紹介しています。草津温泉は日本の有名な温泉地で、春の訪れとともに美しい自然が楽しめます。温泉の湯けむりと共に、周囲の風景が新緑に包まれ、訪れる人々に癒しを提供します。春の草津温泉は、観光客にとって特別な体験をもたらす場所です。' where id = '2OPrgVb-8dAgWRA0iSeQA';
update content_bodies set title = 'Spring at Kusatsu Onsen', description = 'This video introduces the spring season at Kusatsu Onsen.' where id = 'divH6n2m7xq7GmbLS5Nh_';
update content_bodies set title = '草津温泉について', description = '草津温泉は日本三大温泉の一つであり、毎分32,300リットル以上の温泉水が湧き出るという日本一の自然湧出量を誇ります。この豊富な湧出量のおかげで、草津の多くの旅館や温泉施設では、源泉から直接「かけ流しの温泉水」を提供することができます。観光名所である西の河原公園や湯畑では、その驚くべき湧出量を目の当たりにすることができ、各温泉宿でもその体験を楽しむことができます。ぜひ、純粋で自然な温泉水を心ゆくまでお楽しみください。' where id = 'eLwrciMDjmWdAR1JM-c5C';
update content_bodies set title = 'Kusatsu Onsen in English', description = 'Kusatsu Onsen is one of Japan''s three most renowned hot springs, known for its remarkable natural output of hot spring water, exceeding 32,300 liters per minute. This extraordinary flow allows numerous ryokan (traditional inns) and hot spring facilities in the area to provide ''free-flowing hot spring water'' directly from the source. Visitors can observe the impressive volume of hot water at popular locations such as Sai no Kawara Park and Yubatake, and they can also enjoy the experience at various hot spring inns. The natural hot spring water is available for guests to enjoy fully.' where id = 'o4ROmDcAWUU3WB659QJW9';
update content_bodies set title = '草津温泉公式観光アプリの楽しみ方', description = '草津温泉のまち歩きや情報収集に役立つアプリがリリースされました。このアプリの使い方の一部を紹介します。' where id = 'sCZ92Ct-QTnCnhjeCFyNb';
update content_bodies set title = 'How to Enjoy the Kusatsu Onsen Official Tourism App', description = 'A new app has been released that is convenient for exploring the town of Kusatsu Onsen and gathering information! This summary introduces some of its features.' where id = 'jhzTUE0f9LrE9iumQelmU';
update content_bodies set title = 'リトリートのススメ-草津温泉-', description = '日常に追われる私たちにとって、自分に向き合い、ゆったりと考える時間は非常に重要です。慌ただしさを忘れ、いつもと違う温泉旅行を楽しむことで、心身ともにリフレッシュできます。この旅は新しい自分に生まれ変わる機会を提供してくれるため、おすすめのリトリートです。' where id = 'Sq9ooMNkdhtM0NKj73UfW';
update content_bodies set title = 'Recommendation for a Retreat - Kusatsu Onsen', description = 'In our busy daily lives, it is essential to take time to reflect and connect with ourselves. A trip to a hot spring, where you can forget the hustle and bustle, offers a unique experience. This journey allows for a transformation into a new self, making it a highly recommended getaway.' where id = 'svbfJeNRhAXz9MiALaKBk';
update content_bodies set title = '草津温泉 Web movie ｜『 3650＋』', description = '子どもが成長するにつれて、いつの間にか無くなってしまった瞬間がある。それは、一緒にお風呂に入る時間や、子供を抱き上げる瞬間、何気ない会話、肩を並べて笑った感覚など、特別な区切りではなく静かに終わっていく。しかし、温泉にはその続きをそっと差し出してくれる力がある。親子で並んで湯に浸かる時間は、なぜか忘れられない。草津温泉は、日本三名泉の一つで、自然湧出量が日本一を誇り、毎分32,300リットル以上の温泉が湧き出ている。この豊富な湯量は、観光名所でも実感でき、各温泉宿で「源泉かけ流し」を楽しむことができる。' where id = 'bxjuKAKkci5A0JcqKyDnM';
update content_bodies set title = 'Kusatsu Onsen Web Movie ｜ ''3650+''', description = 'As children grow, certain moments quietly fade away—like the time spent bathing together, lifting them up, casual conversations, and shared laughter. These moments don''t end with a special occasion; they simply slip away. However, hot springs have the power to gently offer a continuation of these experiences. The simple act of soaking in the water side by side as parent and child becomes unforgettable. In such places, what was lost can unexpectedly return. Kusatsu Onsen, one of Japan''s three famous hot springs, boasts the highest natural spring flow in the country, providing an abundance of hot spring water. Visitors can enjoy the ''onsen kake-nagashi'' experience at various ryokans and facilities, making it a perfect destination to reconnect with cherished memories.' where id = 'l-tUqbeux7gpb9u-WHW54';
update content_bodies set title = 'Sowing Seeds　〜今日も種をまく〜', description = '静岡県西部の森町一宮に位置するこの里では、古くからの祭りや農業の営みが受け継がれています。このプロジェクトは、里の四季の移り変わりや人々の心のつながりを伝えています。制作は一宮の水と環境を守る会が行い、地域の皆さまや小國神社、Pierre Allardさん、ゲストハウス森と町に特別な感謝を捧げています。撮影・編集は、采 映像制作の小林成彦さんと株式会社filmentsの深瀬泰宏さんが担当しました。' where id = 'p0d-s9Zb7VP1OBpfMlnNY';
update content_bodies set title = 'Sowing Seeds', description = 'In the village of Ichinomiya, located in the western part of Shizuoka Prefecture, the ancient traditions of festivals and agricultural practices are preserved. This project captures the changing seasons of the village and the heartfelt connections of its people. The production is supported by the Ichinomiya Water and Environment Protection Association, with special thanks to the local community, Okuni Shrine, Pierre Allard, and Morimachi Guesthouse. Filming and editing were done by Naruhiko Kobayashi from Sai Video Production and Yasuhiro Fukase from Filments.' where id = 'XyZOHsTPbt7o92I2hLl00';
update content_bodies set title = '大久保と鍛治島 作り手のひと時（静岡県森町）', description = 'このショートムービーは、静岡県の西部に位置する森町の「作り手」たちの生活を紹介しています。森町は美しい自然と伝統を大切にする人々が暮らし、遠州の小京都とも呼ばれています。特に三倉地区の大久保集落と天方地区の鍛冶島集落では、農的な生活を営む人々が自然を守り続けています。この映画は、森に暮らすことの魅力を伝え、ぜひ一度森町を訪れてみることを勧めています。心に響く何かがきっと見つかるでしょう。製作は森町ツーリズム研究会で、ナレーションはフランセスク・プラナスが担当しています。' where id = 'EornUP0Yv0ctZIb_aItzw';
update content_bodies set title = 'Okubo and Kajishima: A Moment with the Makers (Morimachi, Shizuoka)', description = 'This short film showcases the lives of ''makers'' in Morimachi, a town located in the western part of Shizuoka Prefecture, known for its beautiful nature and traditions. Often referred to as ''Little Kyoto of Enshu,'' Morimachi is home to the Okubo and Kajishima communities, where residents maintain an agricultural lifestyle while preserving the stunning natural environment. The film invites viewers to experience the essence of living in the forest and encourages them to visit Morimachi, promising that there is something that will resonate with their hearts. Produced by the Morimachi Tourism Research Association, the film features narration by Francesc Planas and was filmed and edited by Nobuhiko Kobayashi.' where id = '2CqVA4H83eLooA3A9nFVj';
update content_bodies set title = '03 大久保 立体集落の茶園（静岡県森町）', description = '静岡県の西部に位置する森町は、美しい自然と伝統を大切にする人々が暮らし、遠州の小京都と呼ばれています。三倉地区の大久保集落には、急斜面に広がる立体的な茶園があり、農業と生活が息づく空間が形成されています。この地域は、秋葉詣でや塩の商いで賑わった歴史を持ち、戦国時代の雰囲気を感じることができます。訪れる人々は、歴史ある山里の魅力を体験し、この立体集落の面白さを見つけることができるでしょう。森町を訪れることで、心に響く何かを見つけられるかもしれません。' where id = 'U9AeBA_NvAZzzaRRY_PK9';
update content_bodies set title = '03 Okubo Terraced Tea Garden (Morimachi, Shizuoka Prefecture)', description = 'Located in the western part of Shizuoka Prefecture, Morimachi is known for its beautiful nature and the traditions of its people, often referred to as the ''Little Kyoto of Enshu.'' The Okubo settlement in the Mikura district features terraced tea gardens that thrive on steep slopes, creating a vibrant agricultural landscape. This area, once bustling with trade during the Akiba pilgrimage and salt commerce, is rich in history, evoking the spirit of the Warring States period. Visitors can explore the historical mountain village and discover the charm of this unique terraced settlement. The project is produced by the Morimachi Tourism Research Association, aiming to connect people through the beautiful tea gardens. We encourage you to visit Morimachi, where you may find something that resonates with your heart.' where id = 'JgLpvpkxooquio-mChQei';
update content_bodies set title = '02 鍛治島 半夏生への小径（静岡県森町）', description = '静岡県の西部に位置する森町は、美しい自然と伝統を大切にする人々が暮らし、遠州の小京都と呼ばれています。森町北部の天方地区にある鍛冶島集落では、かつての子どもたちの通学路が半夏生が群生する癒しの小径に変わりました。鳥や蛙、虫の音が響き、光と風が木々を揺らす中、春から夏の心地よさや秋から冬の美しさを楽しむことができます。この小径を歩くことで、里山の魅力をぜひ体験してください。「森と生きる」をテーマに、森町を訪れることをお勧めします。' where id = 'uysVQ0rGu3IJc2NYrCWYG';
update content_bodies set title = '02 Kaji Island: Path to Hangesho (Morimachi, Shizuoka Prefecture)', description = 'Located in the western part of Shizuoka Prefecture, Morimachi is known for its beautiful nature and traditional culture, often referred to as the ''Little Kyoto of Enshu.'' The Kaji Island community in the northern part of Morimachi features a path that once served as a school route for children, now transformed into a healing trail lined with Hangesho plants. Visitors can enjoy the sounds of birds, frogs, and insects, as well as the gentle light and breeze through the trees. The path offers a delightful experience of the countryside''s beauty from spring to summer and autumn to winter. The project encourages visitors to explore this charming trail and discover something that resonates with their hearts. Produced by the Morimachi Tourism Research Association and filmed by Kobayashi Design.' where id = 'Su-y_Od3TNNFzSeDQRBFW';
update content_bodies set title = 'NIIGATA GASTRONOMY 2022 _ ショートVer', description = 'このムービーは、インバウンド向けに新潟県の豊かな食文化を表現したものです。県内の各地を撮影し、新潟県の魅力を伝えています。こちらはショートバージョンです。' where id = 'TErcsyckVCyXEhwMFkeUS';
update content_bodies set title = 'NIIGATA GASTRONOMY 2022 _ Short Version', description = 'This is a short film showcasing the rich food culture of Niigata Prefecture, aimed at inbound tourism. It captures various locations within the prefecture to convey the charm of Niigata.' where id = 'KzujCDFEV2iB_9WDCPPDN';
update content_bodies set title = '小坂の滝めぐりー秋ーFull version', description = '小坂の滝めぐりの中で、最も手軽に迫力ある滝とその造形美を楽しめるコースです。じっくりと3時間かけてハイキングを行い、初心者でも楽しむことができますが、特に大迫力の滝が3か所も訪れることができるのが魅力です。' where id = 'KtdekodrbxovRxeYtP21w';
update content_bodies set title = 'Kozaka Waterfall Tour - Autumn - Full Version', description = 'This course offers an easy yet impressive way to enjoy the beauty and power of waterfalls in Kozaka. The hiking tour takes about three hours, making it suitable for beginners while allowing visitors to experience three magnificent waterfalls.' where id = '0kWw0sesI5HeCBTB9E5Am';
update content_bodies set title = '小坂なシャワークライミング・アクティブコース', description = '小坂なシャワークライミングアクティブコースは、フルウエットスーツではなくライトネオプレンを着用して臨む、文字通りアクティブなシャワークライミング体験を提供します。このコースは、冒険に対するアクティブなアプローチを強調しています。' where id = '1zQN2sIXoMWYAtpBwPUlk';
update content_bodies set title = 'Kozaka''s Shower Climbing Active Course', description = 'The Kozaka Shower Climbing Active Course offers a unique experience where participants engage in shower climbing while wearing light neoprene suits instead of full wetsuits. This course emphasizes an active approach to the adventure.' where id = 'WSN5HAuS6IdSwASDQtwFz';
update content_bodies set title = '飛騨大阪：日本の知られざる町 - 夏版', description = '飛騨大阪は中央日本に位置する小さな町で、飛騨高山や下呂温泉の近くにあります。この町には216の滝（高さ5メートル以上）があり、特別な温泉が3つあります。これらの自然の源は活火山である御嶽山です。' where id = 'GNgBDUQJ7_Rc8YrQwvLv0';
update content_bodies set title = 'Hida-Osaka: Unknown Town in Japan - Summer Version', description = 'Hida-Osaka is a small town located in Central Japan, near Hida-Takayama and Gero hot springs. The town is notable for its 216 waterfalls, each at least 5 meters high, and three unique hot springs. The source of these natural features is Mt. Ontake, an active volcano.' where id = 'F3SCWLkCUF6yhQ3Tv0hs9';
update content_bodies set title = '飛騨-大阪自然シリーズ 冬から春のショートエディション', description = 'この動画は、飛騨-大阪の自然を四季ごとに紹介しています。冬から春への移り変わりに焦点を当てたショートエディションです。より長いバージョンも近日中にアップロード予定です。' where id = 'Tg5ycJUCXG3ntaNJfCfPo';
update content_bodies set title = 'Hida-Osaka Nature series Winter to Spring short edition', description = 'This video showcases the natural beauty of Hida-Osaka across different seasons, focusing on the transition from winter to spring. It is a short edition of the series, with a longer version expected to be uploaded soon.' where id = '7w8QtUYE-FC9vwWfZaGds';
update content_bodies set title = '仁郷川ネオWF＆馬ノ倉WF', description = '飛騨-大阪自然シリーズ2020年春では、仁郷川とその周辺の美しさが紹介されています。このシリーズは、地域の自然景観や独自の特徴を強調し、これらの環境を保護する重要性を訴えています。' where id = '9SO9_cdOPv4DlvouNI73F';
update content_bodies set title = 'Nigorigo River Neo-WF&Umanokura WF', description = 'The Hida-Osaka Nature series showcases the beauty of the Nigorigo River and the surrounding areas during the spring of 2020. This series highlights the natural landscapes and unique features of the region, emphasizing the importance of preserving these environments.' where id = 'XjT12BZ_xb02D4n8Cq0WU';
update content_bodies set title = '飛騨-大阪自然シリーズ 2021年冬版', description = '飛騨-大阪は、下呂市の北部に位置し、素晴らしい自然資源が豊富です。特に冬の季節には、凍った滝や雪山、美しい山々を見ることができます。' where id = 'Ve4E1I1oR5_6ofyfSjnX3';
update content_bodies set title = 'Hida-Osaka Nature series 2021 Winter edition', description = 'Hida-Osaka, located in the northern part of Gero city, is rich in natural resources. During the winter season, visitors can enjoy stunning sights such as frozen waterfalls, snow-covered mountains, and beautiful landscapes.' where id = 'sqM2RFuc7qqzRu9ZOYtg-';
update content_bodies set title = '【屋久島】ワーケーション篇（長尺Ver.）', description = '世界自然遺産に登録されている屋久島で、島の独特な時間の流れを感じながら仕事をすることができます。観光やワーケーションに関する施設情報は、指定されたリンクから確認できます。屋久島は自然に囲まれた環境で、リフレッシュしながら仕事をするのに最適な場所です。' where id = 'Wg3AF3nxASVodXL3d8snH';
update content_bodies set title = 'Yakushima: Workation Edition (Long Version)', description = 'Would you like to work while feeling the island''s time on Yakushima, a UNESCO World Heritage site? For information on sightseeing and workation facilities, please visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'K3tcIQ8GMLYAtUWg9LW_4';
update content_bodies set title = 'サーティスリー', description = '映画『サーティスリー』は、愛媛の田舎にある美しく静かな森と寺院を舞台にした神秘的な冒険を描いています。フランスの音楽家によるオリジナルの音楽が、映画に霊的な次元を加えています。監督の松下ユリアは多様な芸術的背景を持ち、彼女の独自のビジョンが反映されています。ユリアは妹のエリカと共に、子供向けの視覚芸術と演劇を専門とするTORANOKOパフォーミングアーツカンパニーを設立しました。現在、ユリアは太宰治の小説『女生徒』の舞台化にも取り組んでいます。' where id = 'P9BLDMHdQ7OpWDDcZcIi_';
update content_bodies set title = 'Thirty three', description = 'The film ''Thirty three'' presents a mystical adventure set in a beautiful and serene forest and a temple located in rural Ehime, Japan. The original music composition by a French musician enhances the spiritual atmosphere of the film. Directed by Yuria Matsushita, who has a diverse artistic background, the film reflects her unique vision. Yuria, along with her sister Erika, founded the TORANOKO Performing Arts Company, focusing on visual and theatrical arts for children. Currently, Yuria is also working on a stage adaptation of Osamu Dazai''s novel ''Schoolgirl''.' where id = 'Dohl8WYpcU8b6GPF3aibs';
update content_bodies set title = '【屋久島】ワーケーション篇～山・滝～（短尺Ver.）', description = '世界自然遺産に登録されている屋久島で、島の独特な時間を感じながら仕事をしてみませんか。観光やワーケーションに関する施設情報は、こちらのリンクからご覧いただけます。https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'RvEc5NwEMl0q-Yw8NyEqq';
update content_bodies set title = 'Yakushima: Workation Edition - Mountains and Waterfalls (Short Version)', description = 'Experience the unique rhythm of Yakushima, a UNESCO World Heritage island, while working. For information on sightseeing and workation facilities, visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'z5lBwyKHfG_D0WTs7Zx1E';
update content_bodies set title = '【種子島】ワーケーション篇（長尺Ver.）', description = '「宇宙に一番近い島」種子島で、島の時間を感じながら仕事をしてみませんか？観光やワーケーション施設の情報は、こちらのリンクからご覧いただけます。https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'OArxW6Jh5u9Xu3kL8FrEQ';
update content_bodies set title = 'Workation on Tanegashima (Long Version)', description = 'Experience working while feeling the island''s rhythm on Tanegashima, known as ''the island closest to space.'' For information on sightseeing and workation facilities, visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'P0kQWdPhjYU8ENQZxG_XR';
update content_bodies set title = '【種子島】ワーケーション篇～海・ヨガ・星～（短尺Ver.）', description = '「宇宙に一番近い島」種子島で、島の時間を感じながら仕事をする体験はいかがでしょうか。観光やワーケーション施設の情報は、こちらのリンクからご覧いただけます。https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'RfQUA93wLVB2AuKnqu_cq';
update content_bodies set title = 'Workation on Tanegashima: Sea, Yoga, and Stars (Short Version)', description = 'Experience working while feeling the island''s rhythm on Tanegashima, known as the island closest to space. For information on sightseeing and workation facilities, visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'CNFY-ORFLvyavaob7Akip';
update content_bodies set title = '【種子島】ワーケーション篇～まとめ～（短尺Ver.）', description = '「宇宙に一番近い島」種子島で、島の時間を感じながら仕事をしてみませんか？観光やワーケーション施設の情報は、こちらのリンクからご覧いただけます。https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 't8_aM61hGDUbawSQyw4sU';
update content_bodies set title = 'Tanegashima: Workation Edition - Summary (Short Version)', description = 'Experience work while feeling the island''s rhythm on Tanegashima, known as ''the island closest to space.'' For information on sightseeing and workation facilities, visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'MdAoaZkbq9NtTSjVAQoHF';
update content_bodies set title = '【vlog】温泉と自然に癒やされる女一人旅｜愛郷ぐんまプロジェクト｜メディアプロモーション課｜群馬県', description = '愛郷ぐんまプロジェクトの第3弾として万座温泉を訪れました。温泉と自然に癒やされ、日頃の疲れをリフレッシュできました。疲れているときもそうでないときも、ぜひ万座温泉に足を運んでみてください。旅の内容は、昼食、万座しぜん情報館、湯畑、薬師堂、熊四郎洞窟、ホテル横の絶景、夕食、星空観賞会、朝食など多岐にわたります。愛郷ぐんまプロジェクトでは、群馬県内の登録宿泊施設に宿泊する群馬県民を対象に、割引やキャッシュバックが提供されます。ただし、新型コロナウイルスの影響で事業が中止される場合があるため、キャンセル料の補償はありませんのでご注意ください。' where id = 'Mou6P7vt40x5zFHQHthx9';
update content_bodies set title = 'Vlog: Healing Solo Trip to Hot Springs and Nature | Aikyou Gunma Project | Media Promotion Division | Gunma Prefecture', description = 'In this third installment of the Aikyou Gunma Project, I visited Manza Onsen! The hot springs and nature helped me unwind and refresh from my daily fatigue. I encourage everyone to visit Manza Onsen, whether you''re feeling tired or not! The vlog includes various segments such as lunch, visits to the Natural Information Center, Yubatake, Yakushido, Kumashiro Cave, and scenic views near the hotel. It also features dinner, a star-gazing event, and breakfast. The Aikyou Gunma Project offers discounts or cashback for eligible residents staying at registered accommodations in Gunma Prefecture. Please note that the project may be suspended due to COVID-19, and there are no compensation policies for cancellations.' where id = 'NEIlaxm-17HUSnQMxJ02a';
update content_bodies set title = '【屋久島】ワーケーション篇～まとめ～（短尺Ver.）', description = '世界自然遺産の島、屋久島で島の時間を感じながら仕事をしてみませんか？観光やワーケーション施設の情報は、こちらのリンクからご覧いただけます。https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'tC69AboZu2qrMzqND8VRC';
update content_bodies set title = 'Yakushima: Workation Edition - Summary (Short Version)', description = 'Experience working while feeling the island''s rhythm on Yakushima, a UNESCO World Heritage site. For information on sightseeing and workation facilities, visit: https://www.pref.kagoshima.jp/ap01/kumageworkation.html' where id = 'ejYfsHSd0jq_Ho-urerPD';
update content_bodies set title = '【vlog】四万温泉スイーツ巡り｜愛郷ぐんまプロジェクト｜メディアプロモーション課｜群馬県', description = '愛郷ぐんまプロジェクトの第3弾として、四万温泉を訪れ、「四万温泉でスイーツ巡り」をテーマにした旅をしました。自然豊かな四万温泉には、美味しいスイーツがたくさんあります。動画では、PUBLIC LANGOLINOやカフェ＆ダイニング〈シマノネ〉、香茶房 おきなやなどの店舗を訪れ、温泉街やその周辺を探索する様子が収められています。また、群馬県民を対象とした宿泊キャンペーンも紹介されており、登録宿泊施設に宿泊することで割引やキャッシュバックが受けられます。このキャンペーンは新型コロナウイルスの状況により変更される可能性があります。各店舗や愛郷ぐんまプロジェクトの詳細は、提供されたリンクを参照してください。' where id = 'KOTkFgQF27d7H8lS4DXFP';
update content_bodies set title = 'Vlog: Exploring Sweets in Shima Onsen | Aikyou Gunma Project | Media Promotion Division | Gunma Prefecture', description = 'In the third installment of the Aikyou Gunma Project, we visited Shima Onsen with the theme of exploring sweets. Shima Onsen, rich in nature, offers a variety of delicious treats. The video includes visits to several locations such as PUBLIC LANGOLINO, Cafe & Dining Shimanone, and Kousabou Okina, as well as exploring the hot spring town and its surroundings. The project also features a discount campaign for Gunma residents staying at registered accommodations, providing cashback options. The campaign is subject to change based on the COVID-19 situation. For more information, viewers can check the links provided for each location and the Aikyou Gunma Project.' where id = 's6riuxV-QvBLjCB0ngKO_';
update content_bodies set title = '【vlog】伊香保温泉一人旅｜愛郷ぐんまプロジェクト｜メディアプロモーション課｜群馬県', description = '第3弾愛郷ぐんまプロジェクトを利用して、伊香保温泉を一人旅で楽しむ様子を紹介します。高崎駅からバスで伊香保温泉に向かい、石段街を散策しながら、玉こんにゃくを食べたり、岸権旅館の足湯で休憩したりしました。大澤屋で水沢うどんの昼食を取り、伊香保ロープウェイでの散策や、伊香保神社での参拝も行いました。紅葉の名所である河鹿橋を訪れ、森秋旅館に宿泊し、地元の特産品を使った夕食を楽しみました。愛郷ぐんまプロジェクトでは、群馬県内の宿泊施設に宿泊する群馬県民に対して割引が提供されており、旅行の参考になる内容です。' where id = 'yp-NztSitP_dI7zTmn_Uc';
update content_bodies set title = 'Vlog: Solo Trip to Ikaho Onsen | Aikyou Gunma Project | Media Promotion Division | Gunma Prefecture', description = 'In this third installment of the Aikyou Gunma Project, I visited Ikaho Onsen with the theme of enjoying the hot spring town on a solo trip. I explored the area on foot, providing insights for those planning to travel to Ikaho Onsen. The vlog includes various activities such as taking a bus from Takasaki Station to Ikaho Onsen, strolling through the stone steps, tasting local delicacies like ''Tama Konnyaku'', and enjoying a foot bath at Kishi-ken Ryokan. I also had lunch at Oosawaya, rode the Ikaho Ropeway, and visited the Ikaho Shrine. The trip featured beautiful autumn scenery at Kajikabashi and ended with a relaxing stay at Morikyu Ryokan. The Aikyou Gunma Project offers discounts for eligible travelers, making it an excellent opportunity to explore the region.' where id = 'MD7sEnAtKpK88-hilCaRH';
update content_bodies set title = '【vlog】男一人で旅する水上温泉｜愛郷ぐんまプロジェクト｜メディアプロモーション課｜群馬県', description = '第３弾愛郷ぐんまプロジェクトを利用して水上温泉を訪れました。旅のテーマは「男一人で旅する水上温泉」で、前半は車、後半は徒歩で観光を楽しみました。このvlogは水上温泉を訪れる際の参考になります。湯原温泉公園やDOAI VILLAGE、谷川岳ロープウェイなどの観光地を巡り、地元のカフェやレストランでの食事も体験しました。また、水族館の見学やドクターフィッシュの体験も含まれています。このvlogは、美しい温泉街での一人旅の魅力を伝え、宿泊施設や地元の観光スポットを紹介しています。愛郷ぐんまプロジェクトでは、対象者に割引が提供されており、地域を探索する絶好の機会となっています。' where id = 'DRIf-5oYUDzCCnUd9-uYY';
update content_bodies set title = 'Vlog: Traveling Alone to Minakami Onsen | Aikyou Gunma Project | Media Promotion Division | Gunma Prefecture', description = 'In this third installment of the Aikyou Gunma Project, I visited Minakami Onsen with the theme of ''Traveling Alone to Minakami Onsen.'' The journey includes a sightseeing route by car in the first half and on foot in the second half. This vlog serves as a reference for anyone planning to travel to Minakami Onsen. The video features various locations such as Yubara Onsen Park, DOAI VILLAGE, and the Tanigawa Ropeway, along with dining experiences at local cafes and restaurants. I also enjoyed activities like visiting an aquarium and trying Dr. Fish. The vlog captures the essence of solo travel in this beautiful onsen town, showcasing the accommodations and local attractions. The Aikyou Gunma Project offers discounts for eligible travelers, making it an excellent opportunity to explore the region.' where id = 'iOHXRQolceT7Dsw1uJwNs';
update content_bodies set title = '愛郷ぐんまプロジェクト「みなかみ温泉郷」｜知事レポート｜群馬県', description = '愛郷ぐんまプロジェクトでは「泊まって！応援キャンペーン」を実施しており、2020年7月31日までの宿泊が割引対象となっています。山本一太群馬県知事はこのキャンペーンを利用してみなかみ温泉に宿泊し、早朝にならまた湖でカヌー体験を行い、土合駅のグランピング施設も訪れました。また、プロジェクトでは草津温泉、四万温泉、伊香保温泉など、群馬県内の他の温泉地も紹介しており、それぞれのプロモーション動画へのリンクも提供されています。' where id = 'iuQSvnO5H2tpx37YwxMQ2';
update content_bodies set title = 'Aikyou Gunma Project ''Minakami Onsen'' | Governor''s Report | Gunma Prefecture', description = 'The Aikyou Gunma Project offers a ''Stay and Support Campaign'' that provides discounts for all stays until July 31, 2020. Governor Ichita Yamamoto utilized this campaign to stay at Minakami Onsen, where he experienced an early morning canoeing session at Narimata Lake and visited the glamping facility at Doai Station. The project also highlights other hot springs in Gunma, including Kusatsu Onsen, Shima Onsen, and Ikaho Onsen, with links to promotional videos for each.' where id = 'wrdS0fzHuka32DgNs1G3R';
update content_bodies set title = '愛郷ぐんまプロジェクト「伊香保温泉」｜知事レポート｜群馬県', description = '愛郷ぐんまプロジェクトでは「泊まって！応援キャンペーン」を実施しており、令和2年7月31日宿泊分まで割引が適用されます。群馬県知事の山本一太氏はこのキャンペーンを利用して伊香保温泉に宿泊し、伊香保のシンボルである石段や伊香保神社、河鹿橋を訪れました。また、草津温泉、四万温泉、みなかみ温泉など他の温泉地も紹介されており、それぞれの動画リンクも提供されています。' where id = '-cZzXQmioijHPtMJcbGZW';
update content_bodies set title = 'Aikyou Gunma Project ''Ikaho Onsen'' | Governor''s Report | Gunma Prefecture', description = 'The Aikyou Gunma Project offers a ''Stay and Support Campaign'' with discounts available for all stays until July 31, 2020. Governor Ichita Yamamoto utilized this campaign to stay at Ikaho Onsen, visiting iconic sites such as the stone steps, Ikaho Shrine, and Kajikabashi Bridge. The project also highlights other onsen locations like Kusatsu, Shima, and Minakami, with links to videos showcasing these areas.' where id = 'u5Luqct5fNyC--uoc5SLL';
update content_bodies set title = '赤城山エリアプロモーションムービー「Mount Akagi ROUND TRIP」（春編）', description = '赤城山広域振興協議会は、女優の手島実優さんを案内役に迎え、赤城山の魅力を伝えるロードムービー風の動画「Mount Akagi ROUND TRIP」を制作しました。この動画では、赤城南面千本桜をはじめ、色とりどりの花々が咲き誇る春の赤城山エリアの美しい風景を紹介しています。ぜひ、この春の赤城山の魅力を体験してください。' where id = 'XUEBqLYa45pqqcNPDZKEp';
update content_bodies set title = 'Mount Akagi ROUND TRIP (Spring Edition) - Promotional Movie for the Akagi Mountain Area', description = 'The Akagi Mountain Regional Promotion Council has produced a video titled ''Mount Akagi ROUND TRIP,'' featuring actress Miyu Tejima, who resides in Maebashi City, as the guide. This road movie-style video showcases the vibrant spring scenery of the Akagi Mountain area, including the beautiful cherry blossoms along the southern slopes and a variety of colorful flowers in full bloom. We invite you to experience the charm of Mount Akagi this spring.' where id = '7bXIvUBSvMnsfUosuzyqk';
update content_bodies set title = 'BIRD''S EYE3「１　雄川堰がおりなす風景」｜建設企画課｜群馬県', description = 'この番組は、平成31年4月6日・7日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介します。群馬県には重要文化財や最新技術を駆使した土木施設が多く存在し、将来に語り継ぐ価値があります。番組では、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを伝えます。甘楽町にある雄川堰は世界かんがい施設遺産に認定されており、水路沿いには四季の花々や紅葉を楽しめる遊歩道があります。また、県道下高尾小幡線は、城下町の情緒を演出するために石畳風の舗装と御影石の縁石が施され、サクラ並木と調和した歴史的な雰囲気を醸し出しています。今回は、桜の季節を待ち侘びる雄川堰とその周辺の風景をお届けします。' where id = '5iYjr__j5DOT6riiuMUQ3';
update content_bodies set title = 'BIRD''S EYE3: ''1. The Landscape Created by the Ougawa Dam'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on April 6 and 7, 2019, highlights the essential civil engineering facilities in our lives. Gunma Prefecture is home to numerous significant cultural properties and modern engineering marvels that are worth preserving for future generations. The program aims to showcase the roles and attractions of these civil engineering structures, sparking interest among children who will carry this knowledge forward. Utilizing drone footage, the program captures the scale and dynamism unique to these facilities. The Ougawa Dam in Kanra Town is recognized as a World Irrigation Heritage site, featuring a walking path adorned with seasonal flowers and autumn foliage. Additionally, the Shimotakao Obata Line is designed with cobblestone-like pavement and granite curbs to enhance the historical ambiance of the castle town, harmonizing with cherry blossom trees. This episode presents the beauty of the Ougawa Dam and its surroundings as they await the cherry blossom season.' where id = '_uDwkwiFJnGJCMthat_d3';
update content_bodies set title = 'BIRD''S EYE3「２　金精峠を開く壮大な除雪風景」', description = 'この番組は、平成31年4月13日・14日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が多数存在し、将来に語り継ぐ価値があります。これらの施設の役割や魅力を広め、子どもたちに興味を持ってもらうために、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えています。国道120号の金精道路は、冬期に雪や凍結のため閉鎖され、安全が確保できない区間があります。平成30年12月25日以降、栃木県境から丸沼スキー場入口までの区間は雪に覆われていました。平成31年4月25日の開通前に、12.1kmの区間で除雪作業が行われ、雪に覆われた金精峠を除雪車で力強く切り開いていきます。' where id = 'FOs8PDm0c1SibymUZUgEk';
update content_bodies set title = 'BIRD''S EYE3: The Grand Snow Removal Scene at Kinsei Pass', description = 'This program, aired on Gunma TV on April 13 and 14, 2019, highlights the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. To promote awareness of these structures and inspire interest among children, a program showcasing civil engineering facilities in the prefecture was created. Utilizing drone footage, the program conveys the scale and dynamism unique to these structures. The Kinsei Road on National Route 120 is closed during winter due to snow and icy conditions, posing safety risks. The section from the Kinsei Tunnel at the Tochigi Prefecture border to the entrance of Marunuma Ski Resort has been covered in snow since December 25, 2018. Before reopening on April 25, 2019, snow removal will take place over a 12.1 km stretch, clearing a path through the snow-covered Kinsei Pass.' where id = 'jfuOd-xb6eJv1MPDehm7b';
update content_bodies set title = 'BIRD''S EYE3「３　歴史ある公園と風景」', description = '群馬テレビで平成31年4月20日・21日に放映されたこの番組では、群馬県内の重要文化財や最新技術を駆使した土木施設を紹介し、将来に語り継ぐ価値を伝えます。土木施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを表現します。特に前橋公園は、明治38年に設立され、4月には200本以上のソメイヨシノが咲き誇るお花見スポットとして知られています。また、公園内には国の重要文化財である臨江閣があり、明治17年に迎賓館として建設され、現在もその歴史を伝えています。' where id = 'eAZouQW9dmGRqAIjXgjW3';
update content_bodies set title = 'BIRD''S EYE3: Historical Parks and Landscapes', description = 'This program, aired on Gunma TV on April 20-21, 2019, highlights the essential civil engineering facilities in Gunma Prefecture, including important cultural properties and modern structures that hold significant value for future generations. The aim is to convey the roles and attractions of these facilities to a wider audience and inspire interest among children. Utilizing drone footage, the program showcases the scale and dynamism unique to civil engineering. One featured location is Maebashi Park, established in 1905, which is renowned for its cherry blossoms, with over 200 Somei Yoshino trees blooming in April. The park also houses Rinkakaku, a national important cultural property built in 1884 as a guesthouse, which has preserved its historical significance to this day.' where id = 'cgh2jr157CM7zCA-ccDx3';
update content_bodies set title = 'BIRD''S EYE3「４　城沼を望む風景」｜建設企画課｜群馬県', description = 'この番組は平成31年4月27日・28日に群馬テレビで放映されました。私たちの生活に欠かせない土木施設は、群馬県内に重要文化財や最新技術を駆使したものなど、将来に語り継ぐ価値のあるものが多く存在します。これらの土木施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組が制作されました。ドローン撮影を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。特に、館林市の城沼では、4月に4300匹のこいのぼりが泳ぎ、壮大な風景が広がります。この光景を一目見ようと、県外からも多くの人が訪れます。また、近くには国の名勝に指定されているつつじが岡公園があり、50品種以上、約1万株のつつじが咲き誇り、こちらも人気の観光スポットです。' where id = 'GYPwbDSDcu-7ING4AKabU';
update content_bodies set title = 'BIRD''S EYE3: ''4. Landscape Overlooking Shironuma'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on April 27-28, 2019. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technologies. To convey the roles and attractions of these facilities and spark interest among future generations, a program showcasing civil engineering sites in the prefecture was produced. Utilizing drone footage, the program captures the scale and dynamism unique to these structures. One highlight is Shironuma in Tatebayashi City, where 4,300 carp streamers can be seen swimming in April, creating a magnificent scene. This site attracts many visitors from outside the prefecture, especially to see the combination of cherry blossoms and carp streamers. Nearby, Tsutsujioka Park, recognized as a national scenic spot, features over 50 varieties and approximately 10,000 azaleas, making it another popular tourist destination.' where id = 'dS_cGfKVO7gNf3f8amqSX';
update content_bodies set title = 'BIRD''S EYE3「６　薗原ダムから望む風景」｜建設企画課｜群馬県', description = 'この番組は令和元年5月11日・12日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないものであり、群馬県内には重要文化財や最新技術を駆使した施設が多数存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。群馬県沼田市の薗原ダムは高さ76.5m、長さ127.6mで、スキージャンプ式の減勢工が特徴です。貯水容量は利根川のダム群の中では比較的小さいですが、流域面積は最も大きいダムです。薗原湖の湖畔は春には桜の名所として賑わい、秋にはエメラルドグリーンの湖に紅葉が映えます。' where id = 'nmOJUVLdzSFCiJHxyNexp';
update content_bodies set title = 'BIRD''S EYE3: ''6. Landscape from Sonohara Dam'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on May 11 and 12, 2019. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technologies. To convey the roles and attractions of these facilities and spark interest in future generations, a program showcasing civil engineering structures in the prefecture was produced. Utilizing drone footage, the program aims to capture the scale and dynamism unique to these structures. The Sonohara Dam in Numata City, Gunma Prefecture, stands 76.5 meters tall and 127.6 meters long, featuring a ski-jump type energy dissipator. Although its water storage capacity is relatively small compared to other dams in the Tone River system, it has the largest drainage area. The lakeside of Sonohara Lake is bustling with cherry blossom viewing in spring and reflects vibrant autumn foliage against its emerald green waters.' where id = 'vjYwtM-_mIUVHqCqvGBDL';
update content_bodies set title = '鳥羽の温泉 ー 日本の公衆浴場への入り方ー', description = '温泉は疲労回復や健康促進に良いとされています。三重県鳥羽市で温泉を楽しむことができます。この地域は、巨大アワビやカキ、エビなどの海産物でも知られています。鳥羽へのアクセスは、名古屋駅から約1.5時間、大阪駅からは約2時間の近鉄特急を利用します。詳細については、近鉄の公式ウェブサイトや地元の旅館組合、観光協会の情報を参照してください。' where id = 'kwAE_haE-6YjAqQTUG7WX';
update content_bodies set title = 'HOT SPRING IN TOBA, JAPAN ー How to enter the Japanese public bathー', description = 'Hot springs are beneficial for relieving fatigue and enhancing overall health. Visitors can enjoy the hot springs in Toba, located in Mie Prefecture, Japan. The area is also known for its seafood, including giant abalones, oysters, and shrimps. To access Toba, it takes about 1.5 hours from Nagoya Station and 2 hours from Osaka Station via Kintetsu Limited Express. For more information, you can visit the Kintetsu railway official website and explore local ryokan associations and tourism resources.' where id = 'Z5-DWdREFrMKtfM3xgMVG';
update content_bodies set title = 'BIRD''S EYE3「７　相俣ダムを望む風景」｜建設企画課｜群馬県', description = 'この番組は令和元年5月18日・19日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。みなかみ町の相俣ダム周辺では、4月中旬に桜がつぼみを付け、山頂には雪が残る不思議な光景が広がります。堤高67mの相俣ダムは、谷地形に建設され、両端を断崖に挟まれた圧倒的な景観を持ち、ロマンあふれるダムです。' where id = 'HWXa4fC8zfSZI4spbX5WG';
update content_bodies set title = 'BIRD''S EYE3: ''7. Landscape Overlooking Aimata Dam'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on May 18-19, 2019, highlighting the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to widely convey the roles and attractions of these structures and spark interest among children who will carry on the legacy. Utilizing drone footage, it captures the scale and dynamism unique to civil engineering. The area around Aimata Dam in Minakami Town showcases a unique spring landscape, with cherry blossoms budding in mid-April and snow remaining on the mountain peaks. The 67-meter high Aimata Dam, built in a valley, presents an overwhelming sight as it is flanked by cliffs, embodying a romantic charm.' where id = 'jpCUaBUthaM57oq2VKPO2';
update content_bodies set title = 'BIRD''S EYE3「８　谷田川から桜を望む風景」｜建設企画課｜群馬県', description = 'この番組は、令和元年5月25日・26日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が多く存在し、将来に語り継ぐ価値があります。これらの施設の役割や魅力を広め、子どもたちに興味を持ってもらうために、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えています。群馬県板倉町を流れる谷田川は、水と共生する独特の文化・景観を持ち、国の「重要文化的景観」に選ばれています。蛭田橋から八間樋橋までの堤防にはソメイヨシノやヤマザクラが咲き、川辺の風景を彩る観光スポットとなっています。' where id = '1iPkSFlTcmau8Vpc2MpgM';
update content_bodies set title = 'BIRD''S EYE3: ''8. Scenic View of Cherry Blossoms from the Yatagawa River'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on May 25-26, 2019, highlights the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. To promote the roles and attractions of these structures and spark interest among children, a program showcasing civil engineering facilities in the prefecture was produced. Utilizing drone footage, the program conveys the scale and dynamism unique to civil engineering. The Yatagawa River in Itakura Town, Gunma Prefecture, offers a unique culture and landscape in harmony with water, recognized as a ''Important Cultural Landscape'' by the national government. The riverbanks from Hiruta Bridge to Hachikenbi Bridge are adorned with cherry blossoms, enhancing the riverside scenery and serving as a cherished tourist spot for local residents.' where id = 'Qozj94Ukx-mxLq_Q6iztO';
update content_bodies set title = 'BIRD''S EYE3「９　桜と清流を楽しむ風景」', description = '群馬テレビで令和元年６月１日・２日に放映されたこの番組では、群馬県内の土木施設の重要性を紹介しています。重要文化財や最新技術を駆使した施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、その役割や魅力を広く伝えることを目的としています。ドローン映像を用いて、土木施設ならではのスケール感やダイナミックさを表現しています。特に沼田市の沼田城址は、五層の天守閣が残り、樹齢400年の御殿桜を含む多くの桜が訪れる人々を迎えています。また、真田が治めた当時の面影を残す水辺の石積みも見どころです。' where id = 'uk5x9u_Zywxufsv6XlQO5';
update content_bodies set title = 'BIRD''S EYE3: Enjoying the Scenery of Cherry Blossoms and Clear Streams', description = 'This program, aired on Gunma TV on June 1 and 2, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to a wider audience and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. One featured site is the Numata Castle ruins in Numata City, which retains the legacy of its five-story keep. The area is adorned with cherry blossoms, including a 400-year-old cherry tree, welcoming visitors. The remnants of stone walls from the time of the Sanada clan further enrich the historical significance of this location.' where id = 'wGeKsY-hb1BvOBCp0VGFC';
update content_bodies set title = 'BIRD''S EYE3「１１　歴史ある風情と商業地区が調和する風景」', description = '群馬テレビで令和元年６月１５日・１６日に放映されたこの番組では、私たちの生活に欠かせない土木施設に焦点を当てています。群馬県には重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。高崎市は約37万人の人口を持ち、商業の中心地として知られています。高崎城は1598年に築かれ、現在も当時の風景を伝える土居や堀、乾櫓、東門が残っています。' where id = 'RABDyZoywgsHqU_attzdl';
update content_bodies set title = 'BIRD''S EYE3: A Landscape Where Historical Charm and Commercial Districts Harmonize', description = 'This program, aired on Gunma TV on June 15-16, 2019, highlights the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to widely convey the roles and attractions of these structures, sparking interest among children who will carry on the legacy. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. Takasaki City, with a population of approximately 370,000, is known as the commercial center of the region, while Maebashi serves as the administrative center. Takasaki Castle, built in 1598 under Tokugawa Ieyasu''s orders, still retains remnants of its historical landscape, including the outer moat and the East Gate.' where id = 'V0uY9BEw3BL5oh4nw62B1';
update content_bodies set title = 'BIRD''S EYE3「１２　陸上競技場フィールドから散水を望む風景」', description = 'この番組は、令和元年6月22日・23日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県内には、重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を伝えます。前橋市にある『正田醤油スタジアム群馬』は、高校総体やJ3ザスパクサツ群馬のホームスタジアムとして利用され、地域の人々に愛されています。天然芝の手入れが行われており、今回はその散水風景を上空から楽しむことができます。' where id = '8-Rfzy4BridUdIAYXG1HG';
update content_bodies set title = 'BIRD''S EYE3: A View of Watering from the Athletic Field', description = 'This program aired on Gunma TV on June 22 and 23, 2019, highlighting the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to convey the roles and attractions of these facilities to a wider audience and inspire interest among children. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. The ''Shoda Soy Sauce Stadium Gunma'' in Maebashi City is featured, serving as a venue for high school athletics and the home stadium for J3''s Thespakusatsu Gunma, beloved by local residents. The stadium, with its natural grass, undergoes meticulous maintenance, and viewers can enjoy the watering scene from above.' where id = 'Tso2OZbJSEi_eLykIJH0V';
update content_bodies set title = 'BIRD''S EYE3「１３　県道桐生田沼線から歴史的建造物を望む風景」｜建設企画課｜群馬県', description = 'この番組は、令和元年6月29日・30日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県には重要文化財に指定された土木施設や最新技術を駆使したものが多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、未来を担う子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を伝えます。県道桐生田沼線は群馬県桐生市と栃木県佐野市を結ぶ道で、桐生は絹織物業を中心に発展した歴史があります。今でも多くの歴史的建造物が残り、重要伝統的建造物保存地区として桐生を象徴する地域です。' where id = 'fTgV8-FAWriIYofUjwguG';
update content_bodies set title = 'BIRD''S EYE3: A View of Historical Buildings from Ken-do Kiryu Tanuma Line | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on June 29 and 30, 2019, highlights the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities that are designated as important cultural properties and utilize the latest technologies, all of which hold significant value for future generations. The program aims to widely convey the roles and attractions of these structures and spark interest among children who will carry on the future. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering facilities. The Ken-do Kiryu Tanuma Line connects Kiryu City in Gunma Prefecture with Sano City in Tochigi Prefecture. Kiryu has a rich history centered around the silk weaving industry, as noted in the Jomo Karuta, and still features many historical buildings, including warehouses and factories with sawtooth roofs. This area is a symbol of Kiryu and is designated as an important traditional building preservation district.' where id = 'BDE4Y0ylG6NQ8jsK3DOsg';
update content_bodies set title = 'BIRD''S EYE3「１４　県道深津伊勢崎線から赤城山を望む風景」', description = 'この番組は、令和元年7月6日・7日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちの興味を引くことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを表現しています。伊勢崎市にある県道深津伊勢崎線は、約1kmの直線道路で、北に向かうと赤城山の美しい景色が広がります。赤城山は四季折々に色を変え、訪れる人々を楽しませてくれます。' where id = 'a_bgoCp63qVo08-zWoOlm';
update content_bodies set title = 'BIRD''S EYE3: A View of Mount Akagi from Ken-do Fukatsu Isesaki Line', description = 'This program, aired on Gunma TV on July 6-7, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Ken-do Fukatsu Isesaki Line in Isesaki City features a rare straight stretch of about 1 km, offering refreshing views, including the seasonal beauty of Mount Akagi to the north.' where id = 'c2Oe_Rsh90DOaPCaZ0dlL';
update content_bodies set title = 'BIRD''S EYE3「１６　高原道路からレンゲツツジ群を望む風景」', description = '群馬テレビで令和元年７月２０日・２１日に放映されたこの番組では、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを伝えます。嬬恋村から長野県東御市を結ぶ高原道路では、６月中旬から７月中旬にかけて約60万株のレンゲツツジが咲き誇り、標高1,800 m～2,000 mの美しい風景を楽しむことができます。' where id = '9ZvTQeHYPyX08-9r4Wx1Z';
update content_bodies set title = 'BIRD''S EYE3: Scenic View of Rhododendron from the Highland Road', description = 'This program aired on Gunma TV on July 20-21, 2019, highlighting the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest in children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Highland Road connecting Tsumagoi Village in Gunma to Togakushi City in Nagano features a stunning display of approximately 600,000 rhododendrons blooming from mid-June to mid-July, creating a vibrant contrast against the green mountains at an elevation of 1,800 to 2,000 meters.' where id = 'VNm2yfC9gy-_0kqHnNF_j';
update content_bodies set title = 'BIRD''S EYE3「１７　高原の大自然を楽しむ風景」', description = 'この番組は、令和元年7月27日・28日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちの興味を引くことを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを伝えます。特に嬬恋村の嬬恋パノラマラインは、爽やかな風が吹くドライブスポットで、愛妻の丘では多くのカップルが愛を叫びます。キャベツ畑と浅間山の風景は映画のような美しさで、多くの映画やCMにも利用されています。夏のドライブに訪れてみてはいかがでしょうか。' where id = 'sjsQ4ibaA0znASvxDMY6P';
update content_bodies set title = 'BIRD''S EYE3: Enjoying the Great Nature of the Highlands', description = 'This program, aired on Gunma TV on July 27-28, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures, sparking interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. One featured location is the Tsumagoi Panorama Line in Tsumagoi Village, a popular driving spot known for its refreshing winds. Along the route, couples visit the ''Lovers'' Hill'' to express their love beneath a bell. The rolling hills of cabbage fields and the distant view of Mount Asama create a cinematic atmosphere, making it a frequent choice for films and commercials. Consider visiting for a refreshing summer drive.' where id = 'Buq70h_6NHGG_JFE8Yf25';
update content_bodies set title = 'BIRD''S EYE3「１８　烏川・高松地区かわまちづくりにより創り出される風景」｜建設企画課｜群馬県', description = '群馬テレビで令和元年８月３日・４日に放映されたこの番組では、群馬県内の重要文化財や最新技術を駆使した土木施設を紹介し、その役割や魅力を広く伝えることを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。烏川・高松地区では、河川空間を活用した『烏川・高松地区かわまちづくり』が進行中で、川のせせらぎや緑豊かな環境を生かし、地域住民に愛されるにぎわいの場を創出することを目指しています。オープンカフェや展望レストハウス、ボート乗り場、水辺のコンサートなどが計画されており、近い将来、人々の笑顔があふれる場所となるでしょう。' where id = 'Hq_ZhToycCcWn7c1Ajsou';
update content_bodies set title = 'BIRD''S EYE3: ''18 - The Landscape Created by the Kawamachi Development in the Karasugawa and Takamatsu Areas'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on August 3rd and 4th, 2019, highlights the essential civil engineering facilities in Gunma Prefecture, including important cultural properties and those utilizing the latest technologies. The aim is to convey the significance and appeal of these structures to the public and inspire future generations. Utilizing drone footage, the program showcases the scale and dynamism unique to civil engineering. The Karasugawa and Takamatsu areas, located near the center of Takasaki City, are undergoing a river project known as ''Kawamachi Development.'' This initiative aims to create a vibrant space loved by both Takasaki citizens and the wider community, featuring open cafes, observation rest houses, boat docks, and waterfront concerts, promising to be a joyful gathering place in the near future.' where id = '9QHPrt8f0OjuLj12mveDS';
update content_bodies set title = 'BIRD''S EYE3「１９　牛池川 水辺の楽校を望む風景」', description = 'この番組は、令和元年８月１０日・１１日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、未来を担う子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を伝えます。牛池川は群馬県前橋市を流れる一級河川で、国土交通省の水辺の学校プロジェクトの一環として整備されました。子どもたちが安全に水辺に近づけるよう、堤防の傾斜を緩やかにし、歩道を整備しました。太陽の光を浴びて輝く水面で遊ぶ子どもたちの姿は、日本の原風景を象徴する光景です。' where id = 'XTagld4R1dkRYYF3_LBlj';
update content_bodies set title = 'BIRD''S EYE3: ''19 Ushikekawa - A View of the Water School''', description = 'This program, aired on Gunma TV on August 10-11, 2019, highlights the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to convey the roles and attractions of these facilities and spark interest among children who will shape the future. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. Ushikekawa is a first-class river flowing through Maebashi City, Gunma Prefecture. As part of the Ministry of Land, Infrastructure, Transport and Tourism''s Water School project, the area has been developed to allow children to safely engage with the natural environment. Enhancements include gentle slopes on embankments and improved walkways, enabling safe access to the riverside. The sight of children playing by the shimmering water under the sun embodies a quintessential image of Japan.' where id = 'OQwucnIyEE-EcqC1l6gKm';
update content_bodies set title = 'BIRD''S EYE3「２０　孫兵衛川からシンボルタワーを望む風景」', description = 'この番組は、令和元年８月１７日・１８日に群馬テレビで放映され、群馬県内の土木施設の重要性を紹介しています。重要文化財や最新技術を駆使した施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、その役割や魅力を広く伝えることを目的としています。ドローン映像を用いて、土木施設ならではのスケール感やダイナミックさを表現しています。邑楽町には、緑豊かな遊歩道や丘が整備された孫兵衛川の調整池があり、そこに高さ約60mのシンボルタワー「未来MiRAi」がそびえ立っています。このタワーからは、南にスカイブリッジ、北に赤城山などの美しい景色が広がり、眼下にはおうら中央公園が広がり、噴水広場では大人も子供も憩いの場を楽しむことができます。' where id = 'B5J73VvfDn2NKQo9fRcCx';
update content_bodies set title = 'BIRD''S EYE3: A View of the Symbol Tower from the Sonbeegawa', description = 'This program, aired on Gunma TV on August 17-18, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. In the town of Oura, an oasis and the 60-meter tall Symbol Tower, MiRAi, stand out against the landscape. The tower, built to symbolize the town''s development, offers views of the Sky Bridge to the south and Mount Akagi to the north. Below, Oura Central Park provides a relaxing space for families, complete with a fountain area for respite.' where id = 'bMJG2uV4cKDGr6yg1fuR6';
update content_bodies set title = '大変なこと全部忘れて現実逃避の群馬リトリートツアーvlog♨️3泊4日🍂🍁', description = 'このvlogでは、群馬でのリフレッシュできるリトリート体験を紹介しています。湯もみと湯蒸しの体験があり、撮影はできませんでしたが、湯もみではお湯をかき混ぜ、汗を流した後、布団とビニールに包まれて発汗する湯蒸しを行いました。これらの体験の後には、ローズティーを飲みながら一息つき、心身ともにリフレッシュできました。日常のストレスから逃れるには最適なリトリートでした。' where id = 'QINjmGNzHnnxuimVzWUvO';
update content_bodies set title = 'Escape Reality with a Relaxing 3-Night, 4-Day Retreat Tour in Gunma', description = 'This vlog captures a rejuvenating retreat experience in Gunma, featuring a unique ''yumomi'' and ''yuzumi'' experience. Although filming was not allowed during the activities, the ''yumomi'' involved vigorously mixing hot water, followed by ''yuzumi,'' where participants are wrapped in blankets and plastic to sweat out toxins. After these invigorating experiences, a refreshing rose tea was enjoyed, providing a moment of relaxation. The retreat was a perfect way to refresh and escape from daily stress.' where id = '-A2DqBauR4UT-mYB-rxV0';
update content_bodies set title = 'BIRD''S EYE3「２１　神流川の水面を望む風景」｜建設企画課｜群馬県', description = 'この番組は令和元年８月２４日・２５日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないものであり、群馬県内には重要文化財や最新技術を駆使した施設が多く存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設のスケール感やダイナミックさを伝えます。神流町を流れる神流川は関東一の清流として知られ、地元住民や県外からも多くの人が訪れます。浅瀬は流れが緩やかで、子供たちが安心して遊べるため、夏休みには笑い声が響き渡ります。川ならではの清涼感を楽しみながら、夏の思い出を作ってみてはいかがでしょうか。' where id = 'dDfPEoAxtFOXnkY60QWke';
update content_bodies set title = 'BIRD''S EYE3: ''21 View of the Water Surface of the Kanagawa River'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on August 24-25, 2019. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant cultural properties and modern structures that are worth preserving for future generations. To promote the roles and attractions of these facilities and spark interest among children, a program showcasing civil engineering structures in the prefecture was created. Utilizing drone footage, the program conveys the scale and dynamism unique to these structures. The Kanagawa River, flowing through Kanra Town, is renowned for its clear waters, attracting many visitors from both within and outside Gunma Prefecture. The gentle shallows allow children to play safely, filling the area with their laughter during summer vacations. Enjoy the refreshing experience that only a river can provide and create lasting summer memories.' where id = 'Fgk273wlPTWseNW8kQ9tB';
update content_bodies set title = 'BIRD''S EYE3「２４　道の駅「中山盆地」から望む風景」｜建設企画課｜群馬県', description = 'この番組は、令和元年９月１４日・１５日に群馬テレビで放映され、群馬県内の土木施設の重要性を紹介しています。重要文化財や最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを伝えます。高山村の道の駅「中山盆地」は、道路利用者の休憩所であり、地域の情報発信や連携の場でもあります。美しい田園風景に囲まれ、心を癒すスポットです。また、田んぼアートのビューポイントでもあり、毎年ボランティアによる田植えで、秋の実りを期待させる作品が楽しめます。' where id = 'FvbJmY8NB4iQKAVG2Gk5E';
update content_bodies set title = 'BIRD''S EYE3: Scenic View from Roadside Station ''Nakayama Bonchi'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on September 14 and 15, 2019, highlights the essential civil engineering facilities in Gunma Prefecture. It showcases various structures, including important cultural properties and those utilizing the latest technologies, emphasizing their significance for future generations. The aim is to raise awareness and interest among children regarding these facilities. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Nakayama Bonchi roadside station in Takayama Village serves as a rest area for road users, a source of information for locals, and a hub for community collaboration. Surrounded by beautiful rural landscapes, it offers a soothing experience. The station is also a viewpoint for rice paddy art, featuring creative works each year, with planting done by volunteers, symbolizing the anticipation of a fruitful autumn.' where id = 'Fl1hcxbpHk78HH_LsZJ3X';
update content_bodies set title = 'BIRD''S EYE3「２５　関越自動車道から望む風景」', description = 'この番組は、令和元年９月２１日・２２日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを表現しています。関越自動車道は、東京都練馬区から新潟県長岡市までを結ぶ高速道路で、今回は渋川から赤城高原サービスエリアまでの区間を紹介します。赤城高原SA（下り）には地元高校生が整備したハイウェイガーデンがあり、上り線では地元の野菜が販売され、多くの人で賑わっています。道中では群馬の山々や利根川の美しい自然が楽しめます。' where id = 'Ve5dqqkjzepiD077jst9w';
update content_bodies set title = 'BIRD''S EYE3: Scenic Views from the Kan-Etsu Expressway', description = 'This program, aired on Gunma TV on September 21 and 22, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that are valuable for future generations. The aim is to communicate the roles and attractions of these structures and to spark interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Kan-Etsu Expressway connects Nerima in Tokyo to Nagaoka in Niigata, passing through Saitama and Gunma. This episode features the section from Shibukawa to Akagi Kogen Service Area, which includes a highway garden maintained by local high school students and a market selling local vegetables, attracting many visitors. The journey offers stunning views of Gunma''s mountains and the Tone River.' where id = 'wHjS72558HutikN7Xs72S';
update content_bodies set title = 'リトリートタイム-Retreat Time -リトリートの聖地 群馬県 （旅人 井森美幸）　｜観光魅力創出課｜群馬県', description = '「リトリート」とは、日常から離れ、心と身体を癒やす旅を指します。群馬県は、穏やかな時の流れと美しい空気に包まれたリトリートの聖地です。ここでは、日々の喧騒を忘れ、心と身体を癒す至福の時間が待っています。神秘的な大自然や大地の恵み、悠久の歴史と文化、静寂の刻を体感できます。ぐんま大使の井森美幸さんと共に、極上のリトリートを体験してみましょう。' where id = 'MUxGyKcSZ3Wq-apG6g_Lc';
update content_bodies set title = 'Retreat Time - A Sacred Place for Retreats in Gunma Prefecture (Traveler Miyuki Imori) | Tourism Attraction Creation Division | Gunma Prefecture', description = 'Retreating means escaping from daily life to heal the mind and body. Gunma Prefecture, a sacred place for retreats, offers a serene flow of time and beautiful air. Here, you can forget the daily hustle and enjoy blissful moments that heal your mind and body. Experience the mystical nature, the blessings of the earth, the timeless history and culture, and the tranquility of the moment. Join Gunma ambassador Miyuki Imori to experience the ultimate retreat.' where id = 'LCDg_O0bR1mY9hnSfRqEY';
update content_bodies set title = 'BIRD''S EYE3「２７　上信電鉄沿線の風景」', description = 'この番組は、令和元年10月5日・6日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在します。これらの役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを伝えます。上信電鉄は高崎市と下仁田町を結び、通学や通勤の重要な交通手段となっています。沿線には、烏川を渡る佐野の渡しや吉井町の田園風景、富岡製紙場の景観など、ローカル鉄道ならではの美しい風景が広がっています。鳥の目線でその魅力を楽しんでください。' where id = '7QupZVvslYUyHubwH8xLM';
update content_bodies set title = 'BIRD''S EYE3: Scenery Along the Joshin Electric Railway', description = 'This program, aired on Gunma TV on October 5-6, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Joshin Electric Railway connects Takasaki City and Shimonita Town, serving as a vital transportation link for students and commuters. The railway line features picturesque local landscapes, including the Sano ferry crossing the Urawa River, the straight rural scenery of Yoshiimachi, and views of the famous Tomioka Silk Mill in Tomioka City. Enjoy the experience from a bird''s-eye perspective.' where id = 'M5VEglkHa2z9Wy-X5B8gC';
update content_bodies set title = 'BIRD''S EYE3「２８　上信自動車道建設がつくりだす風景」', description = 'この番組は、令和元年10月12日・13日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。重要文化財や最新技術を駆使した施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちの興味を引くことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを表現しています。渋川市から吾妻方面へ延びる上信自動車道では、開通に向けて懸命な作業が続けられており、現場からの美しい風景や建設作業員の努力が映し出されています。' where id = '8vxAbAOkNr2M4QHL3GEuq';
update content_bodies set title = 'BIRD''S EYE3: The Landscape Created by the Construction of the Joshinetsu Expressway', description = 'This program, aired on Gunma TV on October 12 and 13, 2019, highlights the essential civil engineering facilities in Gunma Prefecture. It showcases various structures, from important cultural properties to those utilizing the latest technology, emphasizing their significance for future generations. The aim is to raise awareness and interest among children regarding these civil engineering marvels. Utilizing drone footage, the program captures the scale and dynamism unique to these structures. The Joshinetsu Expressway, extending from Shibukawa City to the Agatsuma area, is currently under construction, with dedicated workers striving towards the opening day. The program features the breathtaking views from the construction site and the invaluable landscapes that can only be seen during this phase of development.' where id = '2EjhoZraUeMEoLTxFuZmH';
update content_bodies set title = 'おかえり、本当のわたし。-群馬でリトリート疑似体験-｜観光魅力創出課｜群馬県', description = 'リトリートとは、忙しい日常から離れ、心と身体を癒し、本来の自分を取り戻す新しい旅の形です。群馬県は、首都圏からのアクセスが良く、癒しの温泉や豊かな自然、新鮮な食材が揃っており、リトリートに最適な環境を提供しています。この動画では、群馬県で体験できるリトリートを紹介し、耳と目でその魅力をリアルに体感できる没入感のある映像をお楽しみいただけます。ヘッドホンを推奨し、癒しの音と美しい映像で特別なリトリート時間をお楽しみください。紹介スポットには、温泉三昧の宿四万たむら、奥四万湖でのカヌー、宝徳寺、白井屋ホテル、谷川岳ヨッホなどがあります。' where id = 'kM9ZQeFWOCXCG-YSNG36o';
update content_bodies set title = 'Welcome Back, the Real Me. - Retreat Experience in Gunma - | Tourism Promotion Division | Gunma Prefecture', description = 'A retreat is a new form of travel that allows you to escape from the busy daily life, heal your mind and body, and rediscover your true self. Gunma Prefecture, with its excellent access from the metropolitan area, offers a perfect environment for retreats, featuring soothing hot springs, rich nature, and fresh food. This video introduces retreat experiences available in Gunma, providing an immersive visual experience that allows you to feel its charm through sound and sight. Headphones are recommended to enjoy the healing sounds and beautiful visuals for a special retreat time just for you. The video showcases various spots, including Shima Tamura, Okushimako Canoeing, Hōtokuji Temple, Shiroiya Hotel, Tanigawadake Yōh by Hoshino Resorts, and more.' where id = 'IALjVPx5hQGtcLo13H-uT';
update content_bodies set title = 'BIRD''S EYE3「３０　沼田街道を懐かしむ風景」', description = 'この番組は令和元年10月26日・27日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を伝えます。沼田街道西通りは三国街道や草津街道に通じ、群馬県渋川市には白井宿があります。白井宿は1256年に長尾景仲が白井城を築城し、城下町として発展しました。江戸時代には宿場町として賑わい、当時の地割りや用水路が現在も保存され、多くの人々が訪れています。' where id = 'vNGYIOXb-Sgtdai6yHVPm';
update content_bodies set title = 'BIRD''S EYE3: Nostalgic Scenery of Numata Highway', description = 'This program aired on Gunma TV on October 26-27, 2019, highlighting the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to widely convey the roles and attractions of these structures, sparking interest among children who will carry on the legacy. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. The Numata Highway West Street connects to the Mikuni and Kusatsu highways, featuring Shirai-juku in Shibukawa City, Gunma Prefecture. Shirai-juku originated in 1256 when Nagao Kagenaka was granted the land and built Shirai Castle, leading to the development of the castle town. During the Edo period, it thrived as a post town, and many of its historical layouts and waterways are well-preserved, attracting numerous visitors.' where id = 'iu0pvTpwebvSa5etdE1sZ';
update content_bodies set title = 'BIRD''S EYE3「２９　コンクリートアーチのフォルムと自然が織りなす風景」｜建設企画課｜群馬県', description = 'この番組は、令和元年10月19日・20日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県内には、重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうために制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を表現しています。下仁田町には、懐かしい昭和の風景を醸し出すコンクリートアーチの橋があり、美しい山々と清流に囲まれ、時間を忘れさせる雰囲気があります。橋の下には、逆転層と呼ばれる珍しい地層が見られます。' where id = 'GhHxqUDPh4OM7FevwvZXz';
update content_bodies set title = 'BIRD''S EYE3: ''29 Concrete Arch Form and the Landscape Woven with Nature'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on October 19 and 20, 2019, highlights the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. To convey the roles and attractions of these structures and spark interest among children, a program showcasing civil engineering facilities in the prefecture was produced. Utilizing drone footage, the program aims to express the scale and dynamism unique to civil engineering. In Shinminato Town, a nostalgic concrete arch bridge evokes a Showa-era landscape, surrounded by beautiful mountains and clear streams, creating an atmosphere that makes one forget the passage of time. Below the bridge, jagged rocks can be seen, representing a rare landscape known as inverted strata, formed from ancient sedimentary layers.' where id = 'fwGo-35maQdlc6s-wfUGH';
update content_bodies set title = 'BIRD''S EYE3「３３　わたらせ渓谷鐵道沿線の風景」', description = 'この番組は、令和元年11月16日・17日に群馬テレビで放映され、群馬県内の土木施設の重要性を紹介しています。県内には重要文化財に指定された土木施設や最新技術を用いたものが多く存在し、将来に語り継ぐ価値があります。これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを伝えます。わたらせ渓谷鐵道は、群馬県桐生駅から栃木県日光市の間藤駅を結び、足尾銅山からの銅を運ぶために設置されました。開業当初の鉄道施設が多く現役で、38の施設が登録有形文化財となっています。普通列車のほか、窓のないトロッコ列車も運行しており、四季折々の美しい景色を楽しむことができます。' where id = 'e55nIvg9y0Ay9zhpwj0E2';
update content_bodies set title = 'BIRD''S EYE3: Scenery Along the Watarase Keikoku Railway', description = 'This program, aired on Gunma TV on November 16-17, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures, sparking interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Watarase Keikoku Railway connects Kiryu Station in Gunma to Mito Station in Tochigi, originally built to transport copper from the Ashio Copper Mine. Many of the railway facilities constructed at the time are still in operation, with 38 registered as tangible cultural properties, including stations, bridges, and tunnels. In addition to regular trains, the railway operates an open-air trolley train, allowing passengers to enjoy the stunning seasonal landscapes surrounded by majestic mountains.' where id = 'BdzxzmEt0N88dNY2EJKuL';
update content_bodies set title = 'BIRD''S EYE3「３４　老神渓谷を望む風景」', description = '群馬テレビで令和元年１１月２３日・２４日に放映されたこの番組では、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを表現しています。沼田市の老神渓谷は紅葉の季節を迎え、周囲の山々が色づき始めています。近くには吹割の滝や尾瀬国立公園があり、豊かな自然が楽しめる観光地です。老神温泉はこの渓谷に沿ってあり、静けさを求める観光客が訪れ、非日常的なひと時を過ごしています。' where id = 'UHh7cfWLAyWwpFoloncn4';
update content_bodies set title = 'BIRD''S EYE3: Landscape Overlooking Ougami Valley', description = 'This program aired on Gunma TV on November 23 and 24, 2019. It highlights the essential civil engineering structures in Gunma Prefecture, including important cultural properties and those utilizing the latest technologies. The aim is to convey the significance and appeal of these structures to the public and inspire interest in future generations. Utilizing drone footage, the program showcases the scale and dynamism unique to civil engineering. Ougami Valley in Numata City is particularly beautiful during the autumn season, with surrounding mountains beginning to change color. Nearby attractions include Fukiwari Falls and Oze National Park, offering stunning natural scenery. The Ougami Onsen, located along the valley, provides a tranquil escape for tourists seeking to enjoy the autumn foliage and serenity away from urban life.' where id = 'nfAbPPh8Ij7nd7EXIa1-0';
update content_bodies set title = '2泊3日でゆったり楽しむ群馬のリトリート旅｜草津温泉・四万温泉♨️｜グルメと絶景、温泉を満喫🍲', description = '群馬県の草津温泉と四万温泉を中心にしたリトリート旅の様子を紹介する動画です。癒しのスポットとして、喫茶店や温泉、景色の美しい公園などを訪れた体験が語られています。草津のシンボルである湯畑や熱乃湯の湯もみショー、四万温泉へのドライブなどがハイライトです。また、地元のグルメとしてうどんや川魚料理も紹介されており、奥四万湖の美しい風景も楽しめます。視聴者がこの穏やかな場所への旅行の参考にしてくれることを願っています。' where id = 'RDo7nevoRqaWmcm2aPukm';
update content_bodies set title = 'Relaxing Retreat Trip in Gunma for 2 Nights and 3 Days | Kusatsu Onsen & Shima Onsen | Enjoy Gourmet Food, Scenic Views, and Hot Springs', description = 'This video showcases a relaxing retreat trip in Gunma Prefecture, focusing on the famous Kusatsu Onsen and Shima Onsen. The creator shares their experiences visiting various healing spots, including cafes, hot springs, and scenic parks. Highlights include the iconic Yubatake in Kusatsu, the Yumomi show at Netsunoyu, and a drive to Shima Onsen. The video also features local cuisine, such as udon and river fish dishes, and beautiful views of Lake Oku-Shima. The creator hopes viewers find inspiration for their own trips to these serene destinations.' where id = '4wQurS9NpnWkcpADVi51y';
update content_bodies set title = 'BIRD''S EYE3「４５　自然と歴史を楽しむ風景」', description = 'この番組は、令和２年２月２２日・２３日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県内には、重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設を紹介し、子どもたちの興味を引くことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。桐生市の山上城址公園は、鎌倉時代から戦国期の城の面影を残し、遊具も充実して地域住民に愛されています。また、約150本の蝋梅があり、２月下旬まで早春を楽しむことができます。' where id = 'x1jtOA9QDYONryyJWQNLR';
update content_bodies set title = 'BIRD''S EYE3: Enjoying Nature and History in Landscapes', description = 'This program, aired on Gunma TV on February 22 and 23, 2020, highlights the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The program aims to showcase these facilities to raise awareness and interest among children. Utilizing drone footage, it captures the scale and dynamism unique to civil engineering. One featured site is the Yamagami Castle Ruins Park in Kiryu City, which preserves remnants of the castle from the Kamakura to Sengoku periods. The park now offers various playground equipment, such as roller slides and rope climbing, making it a beloved recreational area for local residents. Additionally, around 150 wax plums bloom in the park, allowing visitors to enjoy an early taste of spring until late February.' where id = '088fk5Bp4JnrWuh7MC59T';
update content_bodies set title = 'BIRD''S EYE3「３６　草木ダム・草木湖を望む風景」｜建設企画課｜群馬県', description = 'この番組は、令和元年12月7日・8日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないものであり、群馬県内には重要文化財や最新技術を駆使した施設が多数存在します。これらの土木施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうために、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。草木ダムは、高さ140メートル、長さ405メートルのコンクリートダムで、国道122号沿いに位置し、紅葉の季節には多くの観光客が訪れます。洪水調整や水力発電などの機能を備えた多目的ダムは、私たちの日常に欠かせない重要な土木施設です。' where id = 'bzZ3dd0yQXAHhrGpq2GlU';
update content_bodies set title = 'BIRD''S EYE3: Landscape Overlooking Kusaki Dam and Kusaki Lake | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on December 7 and 8, 2019. Civil engineering facilities are essential to our daily lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technologies. To convey the roles and attractions of these facilities and spark interest in future generations, a program showcasing civil engineering structures in the prefecture was produced. Utilizing drone footage, the program aims to capture the scale and dynamism unique to these structures. The Kusaki Dam, a concrete dam standing 140 meters tall and 405 meters long, is located along National Route 122, which leads to Nikko City in Tochigi Prefecture. It attracts many tourists during the autumn foliage season and serves as a multipurpose dam for flood control and hydroelectric power generation, making it an invaluable civil engineering facility in our daily lives.' where id = 'oU47-MP-9pvTrKnOQsbXT';
update content_bodies set title = 'BIRD''S EYE3「３７　西野牧大橋から妙義山を望む風景」', description = 'この番組は、令和元年１２月１４日・１５日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在します。これらの役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを伝えます。松井田軽井沢線は群馬県松井田町と長野県軽井沢町を結ぶ道路で、急こう配のカーブが続きます。西野牧大橋からは美しい妙義山の四季折々の姿を楽しむことができますが、運転手は安全運転を心がけるように注意が必要です。' where id = 'snTWd2uxvMvxdSaNWh-sV';
update content_bodies set title = 'BIRD''S EYE3: Scenic View of Myogi Mountain from Nishinomaki Ohashi Bridge', description = 'This program, aired on Gunma TV on December 14 and 15, 2019, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Matsuidakaruizawa Line connects Matsuidamachi in Gunma with Karuizawamachi in Nagano, featuring steep curves that elevate towards Karuizawa. Just before reaching the summit, Nishinomaki Ohashi Bridge offers stunning views of the beautiful Myogi Mountain, which changes with the seasons. However, drivers are reminded to prioritize safety while enjoying the scenery.' where id = 'lNsl4lrv36KpHnX_rVIVz';
update content_bodies set title = 'BIRD''S EYE3「４０　本庄市側から坂東大橋と赤城山を望む風景」', description = 'この番組は、令和２年１月１８日・１９日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県内には重要文化財や最新技術を駆使した土木施設が多数存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちの興味を引くことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。坂東大橋は、埼玉県本庄市と群馬県伊勢崎市を結ぶ橋で、2004年3月に完成しました。橋の長さは936メートルで、晴れた日には赤城山を望むことができ、夕暮れや夜にはライトアップされ、異なる表情を見せます。' where id = 'rZnS-S_XS3JHu__H6Jiin';
update content_bodies set title = 'BIRD''S EYE3: A View of Bandō Bridge and Mount Akagi from Honjo City', description = 'This program, aired on Gunma TV on January 18-19, 2020, highlights the importance of civil engineering structures in our lives. Gunma Prefecture is home to numerous significant civil engineering works, including important cultural properties and those utilizing the latest technologies, which are valuable for future generations. The program aims to convey the roles and attractions of these structures and spark interest among children. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. Bandō Bridge, completed in March 2004, connects Honjo City in Saitama Prefecture and Isesaki City in Gunma Prefecture, spanning 936 meters. The bridge features a central span of 200 meters and offers stunning views of Mount Akagi on clear days, with a different ambiance during sunset and at night when illuminated.' where id = 'DnolrKBQS96lR7RHLN7OM';
update content_bodies set title = 'BIRD''S EYE3「４１　坂本ダムから碓氷湖を望む風景」', description = 'この番組は、令和２年１月２５日・２６日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、その役割や魅力を広く伝えることを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを表現しています。坂本ダムは安中市の碓氷峠に位置し、滑らかに流れる水が特徴で、平成３年には景観や生態系に配慮した『シビックデザイン』に指定されました。ダム湖の碓氷湖には、夢のせ橋とほほえみはしという美しい２本の橋が架かり、遊歩道を歩く人々に楽しさを提供しています。' where id = '-bdj-qywxPP4Jk0tw82oI';
update content_bodies set title = 'BIRD''S EYE3: Scenic View from Sakamoto Dam to Usui Lake', description = 'This program, aired on Gunma TV on January 25-26, 2020, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that hold value for future generations. The aim is to communicate the roles and attractions of these structures to the public and inspire interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. Sakamoto Dam, located on the way to Karuizawa through Usui Pass in Annaka City, is noted for its smooth water flow and was designated as a ''Civic Design'' in 1991 for its consideration of landscape and ecosystem. The dam''s lake, Usui Lake, features two beautiful bridges: the Dream Bridge, known for its elongated silhouette, and the Smile Bridge, which reflects beautifully on the water''s surface, providing enjoyment for pedestrians.' where id = 'hkN06MPWmw0wTSctktHhO';
update content_bodies set title = 'BIRD''S EYE3「４２　東毛広幹道から浅間山、榛名山を望む風景」', description = 'この番組は、令和２年２月１日・２日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを表現しています。東毛広幹道は高崎駅東口から伊勢崎市を経由し、邑楽郡板倉町まで続く約59キロメートルの道で、県央と東毛の交流を促進する主要幹線道路です。平成26年8月に暫定2車線で全線開通し、平成28年7月には4車線化されました。今回は伊勢崎から高崎方面へ移動しながら、玉村町の風景とともに榛名山と浅間山を紹介しました。' where id = 'rE8MyQ31T9NeK2iiHDOGg';
update content_bodies set title = 'BIRD''S EYE3: Scenic View of Mount Asama and Mount Haruna from the Higashi-Mo Hirokan Road', description = 'This program, aired on Gunma TV on February 1-2, 2020, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern facilities that are valuable for future generations. The aim is to communicate the roles and attractions of these structures and to spark interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The Higashi-Mo Hirokan Road stretches approximately 59 kilometers from Takasaki Station''s east exit to Itakura Town in the Oura District, enhancing interaction and collaboration between central and eastern Gunma. The road was fully opened in August 2014 with two lanes and expanded to four lanes by July 2016. The filming took place while traveling from Isesaki towards Takasaki, featuring the landscapes of Tamamura Town along with views of Mount Haruna and Mount Asama.' where id = 'jEqAgGBgJ58QF34n8-MT2';
update content_bodies set title = 'BIRD''S EYE3「４３　昭和橋から望む風景」', description = 'この番組は令和2年2月8日・9日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、次世代の子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。昭和橋は、埼玉県羽生市と群馬県明和町を結ぶ長さ659メートルの橋で、江戸時代には日光裏街道として知られていました。利根川には川俣関所が設けられていましたが、現在は水中に沈んでおり、羽生市側には史跡の碑があります。現在の橋は2006年と2014年に完成した4代目で、交通渋滞の緩和や歩行者の安全確保が期待されています。' where id = 'Q0kvqe0NuplfojBHzOcwc';
update content_bodies set title = 'BIRD''S EYE3: View from Showa Bridge', description = 'This program aired on Gunma TV on February 8 and 9, 2020, highlighting the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which are valuable for future generations. The program aims to convey the roles and attractions of these facilities, sparking interest among children who will carry on the legacy. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. Showa Bridge, a 659-meter-long bridge over the Tone River, connects Hanyu City in Saitama Prefecture to Meiwa Town in Gunma Prefecture. Historically, this route was known as the Nikkō Ura Kaidō during the Edo period, with a checkpoint established at the Tone River. Although the checkpoint site has submerged due to river improvements, a monument stands at the bridge''s Hanyu side. The current bridge, the fourth generation, was completed in 2006 and 2014, addressing previous issues of traffic congestion and pedestrian safety.' where id = '6NVmXl6JYdY-Pb37Xh2n7';
update content_bodies set title = 'BIRD''S EYE3「４４　雄大な景観に浮かぶ橋を眺める風景」', description = 'この番組は、令和2年2月15日・16日に群馬テレビで放映され、群馬県内の重要な土木施設を紹介しています。文化財に指定されたものや最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在します。これらの役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを伝えます。関越自動車道の月夜野ICから新潟方面へ約15分の場所にある橋からは、三国連峰の四季折々の景観やみなかみの町が望めます。ウサギの耳をモチーフにしたベンチや、橋の下に流れる赤谷川、国道17号があり、上からも下からも美しい景観を楽しめる橋です。' where id = 'AWfFPgFpNSkcwtllPmJvk';
update content_bodies set title = 'BIRD''S EYE3: A View of the Bridge Floating in a Majestic Landscape', description = 'This program, aired on Gunma TV on February 15 and 16, 2020, highlights the essential civil engineering structures in Gunma Prefecture. It showcases various significant cultural properties and modern engineering marvels that are valuable for future generations. The aim is to communicate the roles and attractions of these structures and to spark interest among children. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. A notable feature is a bridge located about 15 minutes from the Tsukiyono IC on the Kan-Etsu Expressway, offering views of the seasonal landscapes of the Mikuni Mountain Range and the town of Minakami. The bridge features rabbit ear-shaped benches and is situated above the Akaya River and National Route 17, providing stunning perspectives both from above and below.' where id = 'mFjSvVjKGiGY1e2YN7z35';
update content_bodies set title = 'リトリートぐんま～Re：ここから始まる～【格闘家　堀口　恭司】｜観光魅力創出課｜群馬県', description = '群馬県出身の総合格闘家、堀口恭司選手が心身をリセットするために、リトリートの聖地である群馬県を訪れています。彼は自分自身を見つめ直す旅を通じて、心と体の調和を図っています。この動画には、視聴者が気づくべき不思議な仕掛けが隠されており、それを見破ることでスッキリとした気持ちになれるかもしれません。撮影地には四万湖、ティールーム ゆきうさぎ、尻焼温泉、昔心の宿 金みどり、チャツボミゴケ公園、西の河原公園が含まれています。' where id = 'ZhBA_QMSoHL3dai9zRPcR';
update content_bodies set title = 'Retreat Gunma - Re: It All Starts Here - [MMA Fighter Kyoshi Horiguchi] | Tourism Promotion Division | Gunma Prefecture', description = 'Kyoshi Horiguchi, a mixed martial artist from Gunma Prefecture, embarks on a journey to reset his mind and body in the sacred retreat location of Gunma. As he reflects on himself, viewers are invited to discover hidden elements within the video that can provide a refreshing experience. The filming locations include Shima Lake, Tea Room Yukiusagi, Shiryaki Onsen, Mukashigoto no Yado Kanmidori, Chatubomigoke Park, and Nishi no Kawahara Park.' where id = 'QZqIazBhku9K1QqBNbOsl';
update content_bodies set title = 'BIRD''S EYE3「４６　県道水上片品線から奈良俣ダムを望む風景」', description = 'この番組は、令和２年２月２９日・３月１日に群馬テレビで放映され、私たちの生活に欠かせない土木施設の重要性を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が数多く存在し、将来に語り継ぐ価値があります。番組は、これらの施設の役割や魅力を広く伝え、子どもたちに興味を持ってもらうことを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミック感を伝えます。県道６３号は、みなかみ町から片品村を結び、奈良俣ダムへと続きます。このダムは、堤頂高１５８メートルの多目的ロックフィルダムで、平成３年に完成しました。雪に覆われたダム周辺の風景をお楽しみください。' where id = 'p4Y8Okc1DZ68d4b2GZ2uG';
update content_bodies set title = 'BIRD''S EYE3: Scenic View of Naramata Dam from Prefectural Road 46', description = 'This program, aired on Gunma TV on February 29 and March 1, 2020, highlights the importance of civil engineering facilities in our lives. Gunma Prefecture is home to numerous civil engineering structures, including important cultural properties and those utilizing the latest technologies, which are valuable for future generations. The program aims to convey the roles and attractions of these facilities and spark interest among children who will carry on the legacy. Utilizing drone footage, it showcases the scale and dynamism unique to civil engineering. Prefectural Road 63, connecting Minakami Town to Katashina Village, leads to Naramata Dam, a multipurpose rock-fill dam completed in 1991. The dam features a height of 158 meters and includes a water intake and tunnel to direct water from the adjacent river. Enjoy the winter scenery surrounding the dam.' where id = '-mrPKaK_SZhGBOcMiHCnL';
update content_bodies set title = '鳥羽の冬の味覚ー牡蠣とトロサワラー', description = '三重県鳥羽市では、冬の味覚が楽しめます。特に、今が旬の牡蠣が人気です。鳥羽では、巨大アワビやエビなどの海産物も豊富に揃っています。また、温泉もあり、伝統的な日本の公衆浴場を体験することができます。宿泊を希望する方には、ぜひ日本式の宿、旅館をおすすめします。鳥羽へのアクセスは、名古屋からは1時間半、大阪からは2時間の近鉄特急で便利です。詳細情報は、近鉄鉄道の公式サイトや鳥羽旅館組合、鳥羽市観光協会の公式サイトをチェックしてください。' where id = 'h3dp7ZpVj2SspHCxoMb90';
update content_bodies set title = 'WINTER TASTE IN TOBA, JAPANー Oysters and TORO SAWARAー', description = 'Toba, located in Mie Prefecture, Japan, offers a delightful winter culinary experience, particularly with its seasonal oysters. Visitors can explore various seafood options, including giant abalones and shrimps. The region is also known for its hot springs, providing a unique opportunity to experience traditional Japanese public baths. For those interested in staying overnight, Toba features Japanese-style inns, or ryokans, which are highly recommended. Access to Toba is convenient, with a 1.5-hour journey from Nagoya and a 2-hour trip from Osaka via Kintetsu Limited Express. For more information, visitors can check the official websites of Kintetsu railway, the Toba Ryokan Association, and the Toba Tourism Association.' where id = 'Dendm_umGHi4KAY20JwO3';
update content_bodies set title = 'BIRD''S EYE3「４８　四万川ダム（奥四万湖）を望む風景」', description = 'この番組は令和２年３月１４日・１５日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないものであり、群馬県内には重要文化財や最新技術を駆使した施設が多数存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。四万川ダムは利根川水系の重力式コンクリートダムで、堤高89.5メートルは群馬県で最も高く、西洋の城を思わせるデザインです。上信越高原国立公園内に位置し、下流には四万温泉郷があります。平成６年に『地域に開かれたダム』に指定され、地域の意見を反映した整備が進められています。神秘的なコバルトブルーの湖「奥四万湖」は観光客や地域の人々に愛され、地域の創意工夫を生かした開放的な整備が行われています。' where id = 'aQ9zBE2nuQfTECFAIhg4f';
update content_bodies set title = 'BIRD''S EYE3: Landscape Overlooking Shimagawa Dam (Oku-Shima Lake)', description = 'This program aired on Gunma TV on March 14 and 15, 2020. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technologies. To convey the roles and attractions of these facilities and spark interest among future generations, a program showcasing civil engineering structures in the prefecture was produced. Utilizing drone footage, the program aims to capture the scale and dynamism unique to these structures. The Shimagawa Dam, a gravity concrete dam on the Shimagawa River, stands at 89.5 meters, making it the tallest dam operated by Gunma Prefecture, featuring a design reminiscent of Western castles. Located within the Joshinetsu Kogen National Park, the dam is near the famous Shima Onsen hot spring area. Since being designated as a ''community-open dam'' in April 1994, efforts have been made to develop the surrounding area with community input. The rich nature and the mysterious cobalt blue lake, Oku-Shima Lake, are well-loved by tourists and locals alike, thanks to creative and open development in the area.' where id = 'PK2S0OuFOuhrUohDpT2zY';
update content_bodies set title = 'BIRD''S EYE3「４９　安中榛名駅とラウンドアバウトがつくりだす風景」', description = 'この番組は、令和２年３月２１日・２２日に群馬テレビで放映され、群馬県内の土木施設の重要性を紹介しています。重要文化財や最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、子どもたちにその魅力を伝えることを目的としています。ドローン映像を活用し、土木施設のスケール感やダイナミックさを表現しています。安中市の閑静な住宅街に位置する安中榛名駅は、地域の交通の要所として機能しており、駅から伸びる直線道路では平成３０年度からラウンドアバウトの試験運用が行われています。' where id = 'jSsz4d3NtKjEkJoNUgmHm';
update content_bodies set title = 'BIRD''S EYE3: Landscape Created by Annaka-Haruna Station and Roundabout', description = 'This program aired on Gunma TV on March 21 and 22, 2020, highlighting the essential civil engineering facilities in Gunma Prefecture. It showcases various structures, including important cultural properties and those utilizing the latest technologies, emphasizing their significance for future generations. The aim is to raise awareness and interest among children regarding these civil engineering marvels. Utilizing drone footage, the program captures the scale and dynamism unique to these facilities. Annaka-Haruna Station, located in a quiet residential area of Annaka City, serves as a transportation hub, connecting people to the region. Since fiscal year 2018, a roundabout has been trialed on the straight road extending from the station, indicating the town''s focus on improving transportation.' where id = 'rL5wdJ1s6S7bwyMHjlbfn';
update content_bodies set title = 'BIRD''S EYE3「５０　八ッ場ダム周辺の風景②」｜建設企画課｜群馬県', description = 'この番組は令和２年３月２８日・２９日に群馬テレビで放映されました。私たちの生活に欠かせない土木施設は、県内に重要文化財に指定されたものや最新技術を駆使したものなど、多く存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。八ッ場ダム開発事業は群馬県内最大のビッグプロジェクトであり、長い年月を経て提体が完成し、現在は周辺開発が進行中です。観光や発電、利水など、群馬だけでなく日本全体を支える準備が整えられています。' where id = 'syAE8N8NzeRwBY3Bu16-v';
update content_bodies set title = 'BIRD''S EYE3 ''50 Yamba Dam Surroundings②'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on March 28 and 29, 2020. Civil engineering facilities are essential to our lives, and many significant structures exist in the prefecture, including those designated as important cultural properties and those utilizing the latest technologies. To convey the roles and attractions of these facilities and to spark interest in future generations, a program showcasing civil engineering structures in the prefecture has been produced. Utilizing drone footage, the program aims to convey the scale and dynamism unique to civil engineering. The Yamba Dam development project is one of the largest projects in Gunma Prefecture. After a long period, the dam''s main body has finally been completed, and surrounding developments are underway, preparing for future tourism, power generation, and water supply that will support not only Gunma but also Japan as a whole.' where id = 'fEOIuERBShRpiiFNzyHjf';
update content_bodies set title = '癒しの週末群馬旅行２泊３日。アートホテルと草津温泉でリトリート', description = 'この旅行Vlogでは、群馬県での癒しの週末旅行を紹介しています。2泊3日の旅程は、白井屋ホテルでの快適な滞在から始まります。1日目は前橋市街地を散策し、ホテルでのアート鑑賞を楽しみます。2日目はフィンランドサウナ体験や朝食の後、原美術館ARCを訪れ、草津温泉での夜を過ごします。最終日には朝食を楽しみ、チャツボミゴケ公園を訪れます。動画には各スポットへのリンクやSNS情報も掲載されています。' where id = '2QbjMwuNfwdSkESp4izCc';
update content_bodies set title = 'Healing Weekend Trip to Gunma: 2 Nights and 3 Days at Siroiya Hotel and Kusatsu Onsen Retreat', description = 'This travel vlog showcases a relaxing weekend trip to Gunma, Japan, featuring a 2-night, 3-day itinerary. The journey begins at Siroiya Hotel, where guests can enjoy a comfortable stay. Day 1 includes a stroll through Maebashi city and an evening of art appreciation at the hotel. Day 2 features a Finnish sauna experience, breakfast, and a visit to Hara Museum ARC, followed by a night at Kusatsu Onsen. The final day includes breakfast and a visit to Chatsubomi Moss Park. The video also provides links to various locations and social media for further engagement.' where id = 'f6qKBnJY8RqzN82vYwhob';
update content_bodies set title = '【絶景】リトリートぐんま ～みなかみVlog～', description = '「リトリートの聖地」ぐんまへ。リトリートとは、忙しい日常生活から離れ、心や身体を癒す旅です。今回の旅では、みなかみ町を訪れ、極上の癒し旅を体験します。群馬の美しさと静けさを一緒に探求してみませんか。' where id = '0gK9KZu70tnWZgKzHIhK8';
update content_bodies set title = 'Breathtaking Retreat in Gunma - Minakami Vlog', description = 'Discover Gunma, known as the ''sacred place for retreats.'' A retreat is a journey to heal the mind and body away from the hustle and bustle of daily life. This trip takes you to Minakami Town, where you can experience an ultimate healing journey. Join us in exploring the beauty and tranquility that Gunma has to offer.' where id = 'CwEttv3fPiZkwDsQqP0rR';
update content_bodies set title = 'リトリート in ぐんま～猿ヶ京 癒やしの旅日記～', description = '「リトリートの聖地」ぐんまへ。リトリートとは、忙しい日常生活から離れ、心や身体を癒す旅です。今回の旅では、みなかみ町の「たくみの里」と「猿ヶ京温泉」を訪れました。旅の記録を日記に残すのも良いかもしれません。あなたも、ぐんまで極上の癒し旅をしてみませんか。' where id = 'DEQbreLUT70YYLyYyx5FI';
update content_bodies set title = 'Retreat in Gunma - A Healing Travel Diary in Sarugakyo', description = 'Gunma, known as the ''sacred place for retreats,'' offers a chance to escape the busy daily life and heal both mind and body. This journey takes you to Minakami Town, specifically to ''Takumi no Sato'' and ''Sarugakyo Onsen.'' Keeping a travel diary can be a great way to document your experiences. Why not embark on a luxurious healing journey in Gunma?' where id = 'Z9fUHAZfGVon7h9lsan2F';
update content_bodies set title = 'リトリートぐんま～ここから始まる～【格闘家　堀口　恭司】｜観光魅力創出課｜群馬県', description = '「誰もが、社会・日常生活と向き合い、自分自身と戦っている」というメッセージが伝えられています。がむしゃらに進むだけでなく、時には立ち止まり、自分自身を見つめ直すことが重要です。心身のリセットを図るための時間が必要です。リトリートの聖地である群馬で、新たなスタートを切ってみませんか？撮影地には四万湖、ティールーム ゆきうさぎ、尻焼温泉、昔心の宿 金みどり、チャツボミゴケ公園、西の河原公園が含まれています。' where id = 'CLjczb9uKc2JKYSNXTcN1';
update content_bodies set title = 'Retreat Gunma - A New Beginning with Fighter Kyoshi Horiguchi | Gunma Prefecture Tourism Promotion Division', description = 'Everyone faces challenges in society and daily life, battling with themselves. It''s essential to take a moment to pause and reflect, allowing time for mental and physical reset. Why not start your journey at the retreat haven of Gunma? The filming locations include Shima Lake, Tea Room Yukiusagi, Shiryaki Onsen, Mukashigokoro no Yado Kanmidori, Chatubomigoke Park, and Nishi no Kawahara Park.' where id = 'MCCz530_F9yFSfuXpt7A_';
update content_bodies set title = '格闘家　堀口 恭司  リトリートぐんま　ロケ撮影裏｜観光魅力創出課｜群馬県', description = '「リトリートぐんま～ここから始まる～」の撮影裏をお届けします。メイン動画には盛り込めなかった堀口選手の生の声やリアクションを楽しむことができます。撮影地は四万湖、ティールーム ゆきうさぎ、尻焼温泉、昔心の宿 金みどり、チャツボミゴケ公園、西の河原公園など多岐にわたります。' where id = 'uAtg2OhJgNSgRBwLkgTYP';
update content_bodies set title = 'Martial Artist Kyoshi Horiguchi Behind the Scenes of Retreat Gunma Filming | Gunma Prefecture Tourism Promotion Division', description = 'This video provides a behind-the-scenes look at the filming of ''Retreat Gunma - Where It All Begins!'' Enjoy the genuine voice and reactions of Horiguchi that couldn''t be included in the main video. The filming locations include Shima Lake, Tea Room Yukiusagi, Shiryaki Onsen, Mukashigokoro no Yado Kanmidori, Chatubomigoke Park, and Nishi no Kawahara Park.' where id = 'dnotG2C30DuIfFDX63Did';
update content_bodies set title = 'ぐんま大使ヒデちゃん・井森のリトリート旅in草津（旅人 中山秀征／井森美幸）｜観光魅力創出課｜群馬県', description = 'ぐんま大使の中山秀征さんと井森美幸さんによるリトリート旅の第三弾が草津温泉で開催されます。絶景の温泉や地元のグルメ、群馬の大自然を堪能し、心身ともに癒される内容です。今回が初めての二人旅で、テレビでは見られない素の一面が垣間見えます。旅行に役立つ観光情報や芸能界の裏話も盛り込まれたリトリート旅をぜひご覧ください。' where id = 'Mg8sVdBuK1TFBVHuK2KEd';
update content_bodies set title = 'Hide-chan and Imori''s Retreat Trip in Kusatsu (Travelers Hideyuki Nakayama / Miyuki Imori) | Gunma Prefecture Tourism Promotion Division', description = 'This is the third installment of the retreat trip featuring Gunma ambassadors Hideyuki Nakayama and Miyuki Imori, who visit Kusatsu Onsen! They explore breathtaking hot springs, local gourmet food highly praised by residents, and the unique natural beauty of Gunma, providing a thorough healing experience. This marks the first trip for Nakayama and Imori together, revealing their genuine sides that viewers can''t see on television. The retreat journey includes useful travel information and exclusive stories from the entertainment industry. Don''t miss it!' where id = 'AKOC9Gs5uLsS-LiYm4q-k';
update content_bodies set title = 'おかえり、本当のわたし。-群馬で出会えるリトリート-【後編】', description = 'リトリートとは、忙しい日常から離れ、心と身体を癒やし、本来の自分を取り戻す新しい旅の形です。仕事に疲れた女性が群馬県を訪れ、出会った人々から「おかえり」と声をかけられることで、彼女の暗い表情が次第に明るくなり、本来の自分を取り戻していく様子が描かれています。群馬県は、癒やしの温泉や豊かな自然、おいしい食事が揃い、リトリートに最適な環境が整っています。動画は前編・後編の2部構成で、それぞれ異なるリトリート体験を紹介しています。' where id = 'JTTfB8VYUUaBP21u5nxAV';
update content_bodies set title = 'Welcome Back, the Real Me. - A Retreat Experience in Gunma - Part 2', description = 'A retreat is a new form of travel that allows individuals to step away from their busy daily lives, heal their minds and bodies, and rediscover their true selves. The story follows a woman who, feeling exhausted from work, visits Gunma Prefecture. Throughout her journey, she encounters people who greet her with the words ''Welcome back,'' gradually brightening her previously dark expression and helping her reconnect with her authentic self. Gunma offers an ideal environment for retreats, with its soothing hot springs, rich nature, and delicious food, all conveniently located near the metropolitan area. The video is divided into two parts, showcasing different retreat experiences.' where id = '7gKCko-44QVQo1O0m1BAB';
update content_bodies set title = 'おかえり、本当のわたし。-群馬で出会えるリトリート-【前編】', description = 'リトリートとは、忙しい日常から離れ、心と身体を癒やし、本来の自分を取り戻す新しい旅の形です。仕事に疲れた女性が群馬県を訪れ、出会った人々から「おかえり」と声をかけられることで、次第に暗かった表情が明るくなり、本来の自分を取り戻していく様子が描かれています。群馬県は、癒やしの温泉や豊かな自然、おいしい食が揃い、リトリートに最適な環境が整っています。動画は前編・後編の2部構成で、それぞれ異なるリトリート体験を紹介しています。' where id = 'P30wkir61CiepO04DRG9w';
update content_bodies set title = 'Welcome Back, the Real Me. - A Retreat Experience in Gunma - Part 1', description = 'A retreat is a new form of travel that allows individuals to step away from their busy daily lives, heal their minds and bodies, and rediscover their true selves. The story follows a woman who, feeling exhausted from work, visits Gunma Prefecture. Throughout her journey, she encounters people who greet her with the phrase ''Welcome back,'' gradually brightening her previously dark expression and helping her reconnect with her authentic self. Gunma offers an ideal environment for retreats, with its soothing hot springs, rich nature, and delicious food, all conveniently located near the metropolitan area. The video is divided into two parts, showcasing different retreat experiences.' where id = 'C4Exp_by_Xklr4rySV3RS';
update content_bodies set title = '【石狩市公式動画】観光プロモーション映像（第６回 日本国際観光映像祭(JWTFF) 北海道部門 創造賞(Creative Award)受賞作品）', description = '本映像は、北海道石狩市の観光プロモーション映像で、Adventure、Time Travel、Gourmet Huntの3つのテーマで構成されています。シネマ風の美しい映像で、石狩市の魅力を伝えています。石狩市は札幌市に隣接し、札幌中心部から車で40分の距離にあり、海や山、川などの自然が豊かです。海水浴やキャンプ、乗馬、スノーシュー、果物狩りなどのアウトドア活動が楽しめます。また、日本遺産に認定された歴史的・文化的観光地も多く、港朝市や地物市場で新鮮な農水産物を購入し、地元の美味しい食事を楽しむこともできます。この映像は第6回日本国際観光映像祭で創造賞を受賞しました。' where id = 'ztJvn56-IUk8_g74ZWRDU';
update content_bodies set title = 'Ishikari City Official Video: Tourism Promotion Film (Winner of the Creative Award at the 6th Japan International Tourism Film Festival - Hokkaido Division)', description = 'This is a tourism promotion video for Ishikari City, Hokkaido. The film is structured around three themes: Adventure, Time Travel, and Gourmet Hunt, showcasing the city''s charm through beautiful cinematic visuals. Ishikari City is located just 40 minutes by car from Sapporo, offering easy access to stunning natural landscapes including the sea, mountains, and rivers. Visitors can enjoy outdoor activities such as swimming, camping, horseback riding, snowshoeing, and fruit picking. The city is also home to numerous historical and cultural sites, including those recognized as Japan Heritage. Additionally, fresh agricultural and marine products can be purchased at local markets, allowing visitors to savor delicious meals made from these ingredients. The video won the Creative Award at the 6th Japan International Tourism Film Festival, which is part of a network recognized by UNWTO.' where id = 'gvfAinGqrwTtoDJcSFYMk';
update content_bodies set title = 'SONY | Cinema Line FX3 | 映画的映像 | Tamron 28-75mm F/2.8 | 瀬戸内での撮影', description = 'この動画は、Sony Cinema Line FX3カメラを使用して愛媛の瀬戸内で行ったテスト撮影を紹介しています。制作者は視聴者がコンテンツを楽しんでくれることを願い、サポートに感謝の意を示しています。撮影場所は愛媛と明記されており、チャンネル登録やInstagramフォローのリンクも含まれています。また、動画で使用した音楽の入手先や仕事の問い合わせ先も提供されています。使用機材にはSony Cinema Line FX3、Tamron 28-75mm F/2.8レンズ、Kenko Black Mist No.05フィルターが含まれ、編集はAdobe Premiere Proで行われています。' where id = 'u2W2mJ7yp7BA3l5upLb54';
update content_bodies set title = 'SONY | Cinema Line FX3 | Cinematic footage |Tamron 28-75mm F/2.8 | in SETOUCHI', description = 'This video showcases test shooting in Ehime SETOUCHI using the Sony Cinema Line FX3 camera. The creator expresses hope that viewers will enjoy the content and appreciates their support. The filming location is specified as Ehime, and the video includes links for subscribing to the channel and following on Instagram. The creator also mentions where to find the music used in the video and provides contact information for work inquiries. The equipment used includes the Sony Cinema Line FX3, Tamron 28-75mm F/2.8 lens, and Kenko Black Mist No.05 filter, with editing done in Adobe Premiere Pro.' where id = 'J95-xGJYvO4IjsIcfuWmE';
update content_bodies set title = 'SONY α7Ⅲ -TOKYO Team lab Borderless || DIGITAL ART|| CINEMATIC 40s', description = 'この動画は、チームラボを訪れた様子を紹介しており、アートや現実と非現実の違い、そして現実の本質について考えさせられる内容です。この素晴らしい場所での体験は、創造性や想像力をかき立てます。また、クリエイターはチームラボの創設者である猪子寿之氏に対する尊敬の念を表しています。撮影は東京・お台場のチームラボボーダレスで行われ、スタイリッシュなCMのような短い動画を制作することを目指しています。視聴者には、このアートの旅を楽しんでもらいたいと願っています。' where id = 'k2YhvTnDuJNIeHgN4Co9L';
update content_bodies set title = 'SONY α7Ⅲ -TOKYO Team lab Borderless || DIGITAL ART|| CINEMATIC 40s', description = 'The video showcases a visit to TeamLab, prompting reflections on art, the distinction between reality and unreality, and the essence of reality itself. The experience at this remarkable venue ignites creativity and imagination. The creator expresses admiration for Toshiaki Inoko, the founder of TeamLab. The filming took place at TeamLab Borderless in Odaiba, Tokyo, and the creator aims to present a short video reminiscent of a stylish commercial. Viewers are encouraged to enjoy this artistic journey.' where id = 'Jy0_l3HOQWBuGBhnVeXGh';
update content_bodies set title = '【石狩市】石狩のおいしさを詰め込んだグルメドライブ旅', description = '札幌からアクセスが良く、豊かな自然や絶景、新鮮な農水産物を使ったグルメが楽しめる石狩市は、人気のドライブコースです。このドライブ旅では、地元の美味しさを堪能できるスポットを紹介します。まずは「わがまま農園カフェ」で地元食材を使ったヘルシーなランチを楽しみ、次に「戸田記念墓地公園」で5月中旬のソメイヨシノや10月下旬のイチョウの美しい景色を散策します。「佐藤水産サーモンファクトリー店」では特産の鮭を使ったお土産や海鮮おむすびを楽しみ、最後に「La Potēe」で石狩の食材を使った本格的なフレンチを味わいます。各スポットの詳細は特設ウェブサイトで確認できます。' where id = 'MtrrTUyPAmN5YOiH1tJ4d';
update content_bodies set title = 'Gourmet Drive Trip in Ishikari City', description = 'Ishikari City, easily accessible from Sapporo, is a popular driving destination known for its rich nature, stunning views, and delicious gourmet offerings made from fresh agricultural and marine products. This guide introduces a delightful drive trip filled with the flavors of Ishikari that you’ll want to share with someone special. Highlights include the ''Wagamama Farm Cafe'' offering healthy lunches made with local ingredients, ''Toda Memorial Cemetery Park'' famous for its cherry blossoms in mid-May and colorful ginkgo trees in late October, ''Sato Suisan Salmon Factory'' where you can buy local salmon souvenirs and enjoy popular seafood rice balls, and ''La Potēe'', a friendly French restaurant serving dishes made from Ishikari ingredients. For more detailed information about each spot, visit the special website.' where id = 'rgR_May624QbzESPDaMIK';
update content_bodies set title = '【石狩市公式動画】石狩ニシン漁', description = '石狩（特に厚田地区、浜益地区）はかつてニシン漁で栄えた街であり、衰退の時期もありましたが、近年は回復の兆しを見せています。漁師たちは沖合に出て網を仕掛け、力強く網を引き上げると、次々とニシンが獲れます。今日も大漁で、漁師たちも嬉しそうです。この動画では、実際のニシン漁の様子を間近で見ることができ、大漁の様子を楽しむことができます。また、動画の後半ではニシン料理も紹介されています。' where id = 'ynrkzmrolsSrbJBELgBFd';
update content_bodies set title = 'Ishikari City Official Video: Ishikari Herring Fishing', description = 'Ishikari, particularly the Atsuta and Hamamasu areas, was once a thriving town due to herring fishing. Although there were periods of decline, recent years have shown signs of recovery. Fishermen head out to sea, setting nets and pulling them up with strength, catching herring one after another. Today, the fishermen seem particularly happy with their bountiful catch. This video offers a rare glimpse of actual herring fishing and showcases the impressive haul. The latter part of the video also introduces herring dishes.' where id = 'cX7rMRPq3L17XWrjcJ2Mg';
update content_bodies set title = '【北海道七飯町】恋人の聖地夏 　周遊観光PR', description = '七飯町の恋人の聖地を紹介するプロモーションビデオが制作されました。このプロジェクトには、はこだてわいん、久保田牧場、函館大沼プリンスホテル、山川牧場自然牛乳など、地元の企業が協力しています。撮影は桜谷電設工業とSTUDIO SAKURAが担当しました。この取り組みは、七飯町の観光促進を目的としており、訪れる人々にこのロマンチックなスポットをアピールしています。' where id = 'C1gYX_mSWF_DSP0MuFplb';
update content_bodies set title = 'Nanae Town, Hokkaido: Lover''s Sanctuary Summer Tour Promotion', description = 'A promotional video has been created for the Lover''s Sanctuary in Nanae Town. The project involved collaboration with various local businesses, including Hakodate Wine, Kubota Farm, Hakodate Onuma Prince Hotel, and Yamakawa Farm Natural Milk. The filming was conducted by Sakura Electric Industry and STUDIO SAKURA. The initiative is supported by the local government of Nanae Town, aiming to attract visitors to this romantic destination.' where id = '2ijI8F_6WEC0rPeo-YfU5';
update content_bodies set title = '牧草ロールの季節♪', description = '七飯町の駒ケ岳が一望できる場所での出来事を紹介しています。美しい風景と共に、牧草ロールの季節を楽しむことができる特別な場所です。' where id = 'VsDeXhkPeu2ELv0HRsLPC';
update content_bodies set title = 'Season of Hay Rolls', description = 'A location where you can enjoy a panoramic view of Mount Komagatake in Nanae Town.' where id = 'PR9GpYyqZVJml2NEUxlPv';
update content_bodies set title = '七飯町、北海道', description = 'この動画では、北海道に位置する七飯町を紹介しています。地域の特徴や魅力を紹介しています。' where id = 'Z-C3RWfapD4Xe77Bnl5eR';
update content_bodies set title = 'Nanae, Hokkaido', description = 'This video provides an introduction to Nanae, a town located in Hokkaido, Japan. It showcases the unique features and attractions of the area.' where id = 'Jq-yEriTF5SGHOMFn472t';